    var ctx = commands.RunCtx{
        .io = io,
        .allocator = allocator,
        .out = &out,
        .s = s,
        .store = &store,
        .explorer = &explorer,
        .cfg = cfg,
        .data_dir = data_dir,
        .abs_root = abs_root,
        .root = root,
        .args = args,
        .cmd_args_start = cmd_args_start,
        .no_telemetry = no_telemetry,
        .mcp_deferred_root = mcp_deferred_root,
