  438 | fn readSectionsFromFile(io: std.Io, file: std.Io.File, allocator: std.mem.Allocator) !?std.AutoHashMap(u32, SectionEntry) {
  439 |     var magic_buf: [4]u8 = undefined;
  440 |     const n = file.readPositionalAll(io, &magic_buf, 0) catch return null;
  441 |     if (n != 4 or !std.mem.eql(u8, &magic_buf, &MAGIC)) return null;
  442 | 
  443 |     // offset 4 + 44 = 48: skip version + flags + git_head
  444 |     var sc_buf: [4]u8 = undefined;
  445 |     const scn = file.readPositionalAll(io, &sc_buf, 48) catch return null;
  446 |     if (scn != 4) return null;
  447 |     const section_count = std.mem.readInt(u32, &sc_buf, .little);
  448 | 
  449 |     var result = std.AutoHashMap(u32, SectionEntry).init(allocator);
  450 |     errdefer result.deinit();
