  453 |     for (0..section_count) |_| {
  454 |         var entry_buf: [20]u8 = undefined;
  455 |         const en = file.readPositionalAll(io, &entry_buf, pos) catch return null;
  456 |         if (en != 20) return null;
  457 |         pos += 20;
  458 |         try result.put(
  459 |             std.mem.readInt(u32, entry_buf[0..4], .little),
  460 |             .{
  461 |                 .id = std.mem.readInt(u32, entry_buf[0..4], .little),
  462 |                 .offset = std.mem.readInt(u64, entry_buf[4..12], .little),
  463 |                 .length = std.mem.readInt(u64, entry_buf[12..20], .little),
  464 |             },
  465 |         );
  466 |     }
  467 |     return result;
  468 | }
