  501 | /// Read the git HEAD stored in a snapshot file header. Returns null if
  502 | /// the file doesn't exist, is invalid, or has an all-zero HEAD.
  503 | pub fn readSnapshotGitHead(io: std.Io, path: []const u8) ?[40]u8 {
  504 |     const file = std.Io.Dir.cwd().openFile(io, path, .{}) catch return null;
  505 |     defer file.close(io);
  506 | 
  507 |     var magic_buf: [4]u8 = undefined;
  508 |     const mn = file.readPositionalAll(io, &magic_buf, 0) catch return null;
  509 |     if (mn != 4) return null;
  510 |     if (!std.mem.eql(u8, &magic_buf, &MAGIC)) return null;
  511 | 
  512 |     // offset 4 + 4 = 8: skip version + flags
  513 |     var head_buf: [40]u8 = undefined;
  514 |     const hn = file.readPositionalAll(io, &head_buf, 8) catch return null;
  515 |     if (hn != 40) return null;
  516 | 
  517 |     // Return null for all-zero sentinel (no git HEAD available)
  518 |     if (std.mem.allEqual(u8, &head_buf, 0x00)) return null;
  519 |     // Also handle legacy 0xFF sentinel from older versions
  520 |     if (std.mem.allEqual(u8, &head_buf, 0xFF)) return null;
  521 | 
  522 |     return head_buf;
  523 | }
