  525 | /// Load a snapshot into an Explorer. Populates contents, outlines, and
  526 | /// rebuilds trigram + sparse n-gram indexes from the loaded content.
  527 | /// Returns true on success, false if the snapshot couldn't be loaded.
  528 | pub fn loadSnapshot(
  529 |     io: std.Io,
  530 |     snapshot_path: []const u8,
  531 |     explorer: *Explorer,
  532 |     store: *@import("store.zig").Store,
  533 |     allocator: std.mem.Allocator,
  534 | ) bool {
  535 |     return loadSnapshotValidated(io, snapshot_path, null, explorer, store, allocator);
  536 | }
  537 | 
  538 | /// Load a snapshot with optional repo identity validation.
  539 | /// If `expected_root` is non-null, the snapshot's root_hash must match.
  540 | pub fn loadSnapshotValidated(
  541 |     io: std.Io,
  542 |     snapshot_path: []const u8,
  543 |     expected_root: ?[]const u8,
  544 |     explorer: *Explorer,
  545 |     store: *Store,
  546 |     allocator: std.mem.Allocator,
  547 | ) bool {
  548 |     // Clean up stale temp files from previous crashed writers
  549 |     cleanupStaleTmpFiles(io, snapshot_path);
  550 | 
  551 |     const file = std.Io.Dir.cwd().openFile(io, snapshot_path, .{}) catch return false;
  552 |     defer file.close(io);
  553 | 
  554 |     // Read section table (validates magic internally) — reuse already-open file (#253)
  555 |     var sections = (readSectionsFromFile(io, file, allocator) catch return false) orelse return false;
  556 |     defer sections.deinit();
  557 | 
  558 |     // Parse META section to get expected file_count and root_hash
  559 |     var expected_file_count: ?u32 = null;
  560 |     var meta_root_hash: ?u64 = null;
  561 |     if (sections.get(@intFromEnum(SectionId.meta))) |meta_entry| {
  562 |         if (meta_entry.length <= 256 * 1024 * 1024) blk: {
  563 |             const mb = allocator.alloc(u8, @intCast(meta_entry.length)) catch break :blk;
  564 |             defer allocator.free(mb);
  565 |             const nr = file.readPositionalAll(io, mb, meta_entry.offset) catch break :blk;
  566 |             if (nr != mb.len) break :blk;
  567 |             if (parseJsonU32(mb, "file_count")) |fc| {
  568 |                 expected_file_count = fc;
  569 |             }
  570 |             if (parseJsonU64(mb, "root_hash")) |rh| {
  571 |                 meta_root_hash = rh;
  572 |             }
  573 |         }
  574 |     }
  575 | 
  576 |     // Validate repo identity if requested (issue-41)
  577 |     if (expected_root) |root| {
  578 |         const expected_hash = std.hash.Wyhash.hash(0, root);
  579 |         if (meta_root_hash) |stored_hash| {
  580 |             if (stored_hash != expected_hash) return false;
  581 |         } else {
  582 |             // No root_hash in snapshot — reject if caller requires validation
  583 |             return false;
  584 |         }
  585 |     }
  586 | 
  587 |     if (sections.get(@intFromEnum(SectionId.outline_state)) != null) {
  588 |         return loadSnapshotFast(io, snapshot_path, expected_file_count, explorer, store, allocator) catch false;
  589 |     }
  590 | 
  591 |     // Load CONTENT section — this is the core data
  592 |     const content_entry = sections.get(@intFromEnum(SectionId.content)) orelse return false;
  593 | 
  594 |     // Validate content section fits within actual file size (issue-40: truncation detection)
  595 |     const file_stat = file.stat(io) catch return false;
  596 |     const file_size = file_stat.size;
  597 |     if (content_entry.offset + content_entry.length > file_size) return false;
  598 | 
  599 |     var read_pos: u64 = content_entry.offset;
  600 |     const snap_mtime: i128 = @intCast(file_stat.mtime.nanoseconds);
  601 |     var bytes_read: u64 = 0;
  602 |     var file_count: u32 = 0;
  603 |     while (bytes_read < content_entry.length) {
  604 |         // Read path_len(u16)
  605 |         var pl_buf: [2]u8 = undefined;
  606 |         const pln = file.readPositionalAll(io, &pl_buf, read_pos) catch return false;
  607 |         if (pln != 2) break;
  608 |         read_pos += 2;
  609 |         const path_len = std.mem.readInt(u16, &pl_buf, .little);
  610 |         if (path_len == 0 or path_len > 4096) break; // sanity cap
  611 |         bytes_read += 2;
  612 | 
  613 |         // Read path
  614 |         const path_buf = allocator.alloc(u8, path_len) catch return false;
  615 |         defer allocator.free(path_buf);
  616 |         const prn = file.readPositionalAll(io, path_buf, read_pos) catch return false;
  617 |         if (prn != path_len) break;
  618 |         read_pos += path_len;
  619 |         bytes_read += path_len;
  620 | 
  621 |         // Read content_len(u32)
  622 |         var cl_buf: [4]u8 = undefined;
  623 |         const cln = file.readPositionalAll(io, &cl_buf, read_pos) catch return false;
  624 |         if (cln != 4) break;
  625 |         read_pos += 4;
  626 |         const content_len = std.mem.readInt(u32, &cl_buf, .little);
  627 |         if (content_len > 64 * 1024 * 1024) break; // sanity cap: 64MB per file
  628 |         bytes_read += 4;
  629 | 
  630 |         // Read content
  631 |         const content = allocator.alloc(u8, content_len) catch return false;
  632 |         defer allocator.free(content);
  633 |         const crn = file.readPositionalAll(io, content, read_pos) catch return false;
  634 |         if (crn != content_len) break;
  635 |         read_pos += content_len;
  636 |         bytes_read += content_len;
  637 | 
  638 |         // Re-index from disk if file was modified after the snapshot
  639 |         var disk_content: ?[]u8 = null;
  640 |         if (snap_mtime > 0) blk: {
  641 |             // statFile (no open/close): only the mtime is needed here.
  642 |             const ds = std.Io.Dir.cwd().statFile(io, path_buf, .{}) catch break :blk;
  643 |             const ds_mtime: i128 = @intCast(ds.mtime.nanoseconds);
  644 |             if (ds_mtime <= snap_mtime) break :blk;
  645 |             disk_content = std.Io.Dir.cwd().readFileAlloc(io, path_buf, allocator, .limited(16 * 1024 * 1024)) catch break :blk;
  646 |         }
  647 |         defer if (disk_content) |dc| allocator.free(dc);
  648 |         const effective = if (disk_content) |dc| dc else content;
  649 | 
  650 |         // Index into explorer (this dupes path and content internally)
  651 |         explorer.indexFile(path_buf, effective) catch continue;
  652 | 
  653 |         // Record in store for sequence tracking
  654 |         const hash = std.hash.Wyhash.hash(0, effective);
  655 |         _ = store.recordSnapshot(path_buf, effective.len, hash) catch {};
  656 | 
  657 |         file_count += 1;
  658 |     }
  659 | 
  660 |     // Validate file_count matches META expectation (issue-40)
  661 |     if (file_count == 0) return false;
  662 |     if (expected_file_count) |expected| {
  663 |         if (file_count != expected) return false;
  664 |     }
  665 | 
  666 |     // Load frequency table if present
  667 |     if (sections.get(@intFromEnum(SectionId.freq_table))) |freq_entry| {
  668 |         if (freq_entry.length == 256 * 256 * 2) {
  669 |             const index_mod = @import("index.zig");
  670 |             const ft = allocator.create([256][256]u16) catch return file_count > 0;
  671 |             var bulk_buf: [256 * 256 * 2]u8 = undefined;
  672 |             const nr = file.readPositionalAll(io, &bulk_buf, freq_entry.offset) catch {
  673 |                 allocator.destroy(ft);
  674 |                 return file_count > 0;
  675 |             };
  676 |             if (nr != bulk_buf.len) {
  677 |                 allocator.destroy(ft);
  678 |                 return file_count > 0;
  679 |             }
  680 |             for (0..256) |a| {
  681 |                 for (0..256) |b| {
  682 |                     ft[a][b] = std.mem.readInt(u16, bulk_buf[(a * 256 + b) * 2 ..][0..2], .little);
  683 |                 }
  684 |             }
  685 |             index_mod.setFrequencyTable(ft);
  686 |             allocator.destroy(ft);
  687 |         }
  688 |     }
  689 | 
  690 |     return true;
  691 | }
