  693 | fn deinitOutlineStateMap(map: *std.StringHashMap(FileOutline), allocator: std.mem.Allocator) void {
  694 |     var iter = map.iterator();
  695 |     while (iter.next()) |entry| {
  696 |         allocator.free(entry.key_ptr.*);
  697 |         entry.value_ptr.deinit();
  698 |     }
  699 |     map.deinit();
  700 | }
