  702 | fn readSectionInt(comptime T: type, buf: []const u8, cursor: *usize) !T {
  703 |     const size = @sizeOf(T);
  704 |     if (cursor.* + size > buf.len) return error.InvalidData;
  705 |     const value = std.mem.readInt(T, buf[cursor.*..][0..size], .little);
  706 |     cursor.* += size;
  707 |     return value;
  708 | }
  709 | 
  710 | fn readSectionByte(buf: []const u8, cursor: *usize) !u8 {
  711 |     if (cursor.* >= buf.len) return error.InvalidData;
  712 |     const value = buf[cursor.*];
  713 |     cursor.* += 1;
  714 |     return value;
  715 | }
  716 | 
  717 | fn readSectionString(buf: []const u8, cursor: *usize, allocator: std.mem.Allocator, max_len: usize) ![]u8 {
  718 |     const len = try readSectionInt(u16, buf, cursor);
  719 |     if (len > max_len) return error.InvalidData;
  720 |     if (cursor.* + len > buf.len) return error.InvalidData;
  721 |     const out = try allocator.dupe(u8, buf[cursor.* .. cursor.* + len]);
  722 |     cursor.* += len;
  723 |     return out;
  724 | }
  725 | 
  726 | /// Like readSectionString but returns a slice that aliases `buf` (no copy, no
  727 | /// allocation). Valid only while `buf` is alive — callers that retain the
  728 | /// result must keep `buf` alive at least as long (see loadOutlineStateMap).
  729 | fn readSectionStringBorrowed(buf: []const u8, cursor: *usize, max_len: usize) ![]const u8 {
  730 |     const len = try readSectionInt(u16, buf, cursor);
  731 |     if (len > max_len) return error.InvalidData;
  732 |     if (cursor.* + len > buf.len) return error.InvalidData;
  733 |     const out = buf[cursor.* .. cursor.* + len];
  734 |     cursor.* += len;
  735 |     return out;
  736 | }
  737 | /// On success, `backing_out.*` is set to the raw outline_state section buffer
  738 | /// and ownership transfers to the caller (the restored FileOutlines borrow
  739 | /// their import/symbol strings as slices into it — see FileOutline.borrows_strings).
  740 | /// On any error the buffer is freed here and `backing_out.*` is left null.
  741 | ///
  742 | /// The backing buffer is allocated from `backing_allocator` (the Explorer's
  743 | /// allocator), NOT `allocator` (the per-load allocator): it is retained by the
  744 | /// Explorer and must share its lifetime/allocator. Everything else (the map,
  745 | /// keys/paths) uses `allocator` exactly as before.
  746 | fn loadOutlineStateMap(io: std.Io, snapshot_path: []const u8, allocator: std.mem.Allocator, backing_allocator: std.mem.Allocator, expected: ?u32, backing_out: *?[]const u8) !std.StringHashMap(FileOutline) {
  747 |     backing_out.* = null;
  748 |     const bytes = (try readSectionBytes(io, snapshot_path, .outline_state, backing_allocator)) orelse return error.InvalidData;
  749 |     // Kept alive on success (handed to backing_out); freed here on any error.
  750 |     var release_bytes = true;
  751 |     defer if (release_bytes) backing_allocator.free(bytes);
  752 | 
  753 |     var result = std.StringHashMap(FileOutline).init(allocator);
  754 |     errdefer deinitOutlineStateMap(&result, allocator);
  755 |     // Pre-size to the known file count: the map otherwise grows 0 -> ~N with
  756 |     // ~log2(N) rehashes, each re-hashing every entry inserted so far.
  757 |     if (expected) |e| result.ensureTotalCapacity(e) catch {};
  758 | 
  759 |     var cursor: usize = 0;
  760 |     const file_count = try readSectionInt(u32, bytes, &cursor);
  761 |     for (0..file_count) |_| {
  762 |         // `path` is the map key and stays individually owned (deinitOutlineStateMap
  763 |         // / Explorer.deinit free it). Only the import/symbol strings are borrowed.
  764 |         const path = try readSectionString(bytes, &cursor, allocator, 4096);
  765 |         if (path.len == 0) return error.InvalidData;
  766 |         errdefer allocator.free(path);
  767 | 
  768 |         var outline = FileOutline.init(allocator, path);
  769 |         outline.borrows_strings = true;
  770 |         errdefer outline.deinit();
  771 | 
  772 |         const language_raw = try readSectionByte(bytes, &cursor);
  773 |         outline.language = std.enums.fromInt(Language, language_raw) orelse return error.InvalidData;
  774 |         outline.line_count = try readSectionInt(u32, bytes, &cursor);
  775 |         outline.byte_size = try readSectionInt(u64, bytes, &cursor);
  776 | 
  777 |         const import_count = try readSectionInt(u32, bytes, &cursor);
  778 |         try outline.imports.ensureTotalCapacity(allocator, import_count);
  779 |         for (0..import_count) |_| {
  780 |             const imp = try readSectionStringBorrowed(bytes, &cursor, std.math.maxInt(u16));
  781 |             outline.imports.appendAssumeCapacity(imp);
  782 |         }
  783 | 
  784 |         const symbol_count = try readSectionInt(u32, bytes, &cursor);
  785 |         try outline.symbols.ensureTotalCapacity(allocator, symbol_count);
  786 |         for (0..symbol_count) |_| {
  787 |             const name = try readSectionStringBorrowed(bytes, &cursor, std.math.maxInt(u16));
  788 |             if (name.len == 0) return error.InvalidData;
  789 | 
  790 |             const kind_raw = try readSectionByte(bytes, &cursor);
  791 |             const kind = std.enums.fromInt(SymbolKind, kind_raw) orelse return error.InvalidData;
  792 |             const line_start = try readSectionInt(u32, bytes, &cursor);
  793 |             const line_end = try readSectionInt(u32, bytes, &cursor);
  794 |             const has_detail = try readSectionByte(bytes, &cursor);
  795 |             const detail = switch (has_detail) {
  796 |                 0 => null,
  797 |                 1 => try readSectionStringBorrowed(bytes, &cursor, std.math.maxInt(u16)),
  798 |                 else => return error.InvalidData,
  799 |             };
  800 | 
  801 |             outline.symbols.appendAssumeCapacity(Symbol{
  802 |                 .name = name,
  803 |                 .kind = kind,
  804 |                 .line_start = line_start,
  805 |                 .line_end = line_end,
  806 |                 .detail = detail,
  807 |             });
  808 |             outline.name_len_mask |= explore_mod.FileOutline.nameLenBit(name.len);
  809 |         }
  810 | 
  811 |         try result.put(path, outline);
  812 |     }
  813 | 
  814 |     if (cursor != bytes.len) return error.InvalidData;
  815 |     // Success: transfer the backing buffer to the caller.
  816 |     backing_out.* = bytes;
  817 |     release_bytes = false;
  818 |     return result;
  819 | }
