  821 | fn rebuildDepsFromOutline(explorer: *Explorer, path: []const u8, outline: *const FileOutline, allocator: std.mem.Allocator) !void {
  822 |     var deps: std.ArrayList([]const u8) = .empty;
  823 |     errdefer deps.deinit(allocator);
  824 |     try deps.ensureTotalCapacity(allocator, outline.imports.items.len);
  825 | 
  826 |     // Dedup like Explorer.rebuildDepsFor: a file importing the same module more
  827 |     // than once (e.g. ../foo for both a type and a value) must not produce
  828 |     // duplicate forward edges, so a snapshot-restored graph matches a fresh one.
  829 |     var seen = std.StringHashMap(void).init(allocator);
  830 |     defer seen.deinit();
  831 | 
  832 |     for (outline.imports.items) |imp| {
  833 |         // Same resolution as Explorer.rebuildDepsFor: relative specifiers
  834 |         // resolve to repo paths so restored deps match a freshly-indexed graph.
  835 |         const dep = (try explore_mod.resolveDependencyKey(&explorer.dep_graph, outline.path, imp, allocator)) orelse continue;
  836 |         const gop = try seen.getOrPut(dep);
  837 |         if (gop.found_existing) continue;
  838 |         deps.appendAssumeCapacity(dep);
  839 |     }
  840 | 
  841 |     try explorer.dep_graph.setDeps(path, deps);
  842 | }
