  844 | // Process max-RSS in bytes (macOS getrusage reports bytes; Linux reports KiB).
  845 | // Profiler-only: attribution of load-phase memory growth, not a public API.
  846 | fn loadMaxRssBytes() u64 {
  847 |     if (@import("builtin").os.tag == .windows) {
  848 |         // getrusage is POSIX-only; RSS profiling is unavailable on Windows.
  849 |         return 0;
  850 |     } else {
  851 |         var ru: std.c.rusage = undefined;
  852 |         if (std.c.getrusage(0, &ru) != 0) return 0;
  853 |         const raw: u64 = @intCast(@max(0, ru.maxrss));
  854 |         return if (@import("builtin").os.tag == .linux) raw * 1024 else raw;
  855 |     }
  856 | }
  857 | // Written only when `load_prof` is set by loadSnapshotFast; the loader is
  858 | // single-threaded so plain vars are safe.
  859 | var load_prof: bool = false;
  860 | var prof_content_ns: i128 = 0;
  861 | var prof_deps_ns: i128 = 0;
  862 | var prof_symidx_ns: i128 = 0;
  863 | 
  864 | fn insertRestoredFile(
  865 |     explorer: *Explorer,
  866 |     path: []const u8,
  867 |     content: []const u8,
  868 |     outline: FileOutline,
  869 |     allocator: std.mem.Allocator,
  870 |     borrow_content: bool,
  871 | ) !void {
  872 |     var restored_outline = outline;
  873 |     restored_outline.path = path;
  874 | 
  875 |     const outline_gop = try explorer.outlines.getOrPut(path);
  876 |     if (outline_gop.found_existing) return error.InvalidData;
  877 |     outline_gop.key_ptr.* = path;
  878 |     outline_gop.value_ptr.* = restored_outline;
  879 | 
  880 |     // When the content was read from an mmap the Explorer has adopted, store a
  881 |     // borrowed (zero-copy) cache value; otherwise dupe it as usual.
  882 |     const t_content: i128 = if (load_prof) cio.nanoTimestamp() else 0;
  883 |     if (borrow_content) {
  884 |         try explorer.contents.putBorrowed(path, content);
  885 |     } else {
  886 |         try explorer.contents.put(path, content);
  887 |     }
  888 |     if (load_prof) prof_content_ns += cio.nanoTimestamp() - t_content;
  889 | 
  890 |     const t_deps: i128 = if (load_prof) cio.nanoTimestamp() else 0;
  891 |     try rebuildDepsFromOutline(explorer, path, &restored_outline, allocator);
  892 |     if (load_prof) prof_deps_ns += cio.nanoTimestamp() - t_deps;
  893 | 
  894 |     // Mirror commitParsedFileOwnedOutline (explore.zig:872): symbol_index is built
  895 |     // eagerly on every ingest and has NO lazy rebuild trigger. resolveCallees reads
  896 |     // it without a fallback (#524 perf note), so restored files must populate it
  897 |     // here or call-graph edges into them are lost after a snapshot load. had_prior
  898 |     // is false: insertRestoredFile errors above if the path already exists.
  899 |     const t_symidx: i128 = if (load_prof) cio.nanoTimestamp() else 0;
  900 |     explorer.rebuildSymbolIndexFor(path, &restored_outline, false);
  901 |     if (load_prof) prof_symidx_ns += cio.nanoTimestamp() - t_symidx;
  902 | 
  903 |     // Restored files are absent from word_index and trigram_index at load time
  904 |     // (both are rebuilt lazily/incrementally). Register the path in
  905 |     // skip_trigram_files so searchContent's Tier 3 scans its content; without
  906 |     // this the file falls out of every search tier the moment the trigram index
  907 |     // is non-empty (Tier 5's full scan is then ruled out). Mirrors the
  908 |     // outline-only branch of commitParsedFileOwnedOutline. See #507 / #537.
  909 |     try explorer.skip_trigram_files.put(path, {});
  910 | }
