  912 | // Below this many files the per-file freshness stats run on the loading thread:
  913 | // spawning workers for a small tree costs more than the stats they save. Setting
  914 | // CODEDB_LOAD_WORKERS overrides the worker count (and forces parallelism below the
  915 | // threshold) for A/B measurement. Public so a test can size a fixture that
  916 | // deterministically exercises the multi-worker path.
  917 | pub const FRESHNESS_PARALLEL_THRESHOLD: usize = 256;
  918 | 
  919 | // Worker cap for the parallel freshness scan. statFile is dominated by kernel VFS
  920 | // work, not CPU, so throughput saturates at low concurrency: a worker sweep over a
  921 | // 16k-file tree (20 P-core M3 Ultra, files across 200 dirs) measured freshness
  922 | // 14.1ms@1 -> 5.7ms@4 -> 9.5ms@8 -> 13.3ms@12 — a U-curve bottoming at ~4 regardless
  923 | // of core count. More workers past that regress (syscall/cache contention), so cap
  924 | // low rather than at the CPU count. CODEDB_LOAD_WORKERS overrides for re-tuning.
  925 | const FRESHNESS_MAX_WORKERS: usize = 4;
  926 | 
  927 | // One parsed CONTENT-section record. `path` and `content` are borrowed slices into
  928 | // the mapped content section (alive for the whole load) — never owned here; the
  929 | // insert pass copies whatever it keeps.
  930 | const LoadRecord = struct {
  931 |     path: []const u8,
  932 |     content: []const u8,
  933 |     stored_hash: ?u64,
  934 | };
  935 | 
  936 | // Outcome of one file's freshness check: was the on-disk file modified after the
  937 | // snapshot? The scan only stats — no content read, no allocation — so workers stay
  938 | // pure and trivially thread-safe; the insert pass reads fresh content (sequentially,
  939 | // one file at a time) for the rare stale ones.
  940 | const LoadFreshness = struct {
  941 |     stale: bool = false,
  942 | };
  943 | 
  944 | // Freshness scan for one chunk of records: statFile each path (one syscall, no
  945 | // open/close) and flag it stale when its mtime is newer than the snapshot. Pure
  946 | // read-only and allocation-free, so workers run this over disjoint chunks
  947 | // concurrently; each writes only its own slice of `out`.
  948 | fn freshnessScan(io: std.Io, snap_mtime: i128, recs: []const LoadRecord, out: []LoadFreshness) void {
  949 |     for (recs, out) |record, *fr| {
  950 |         const ds = std.Io.Dir.cwd().statFile(io, record.path, .{}) catch continue;
