const std = @import("std");
const cio = @import("cio.zig");
const ContentCache = @import("hot_cache.zig").ContentCache;

// ── Inverted word index ─────────────────────────────────────
// Maps word → list of (path, line) hits. O(1) word lookup.

pub const WordHit = struct {
    doc_id: u32,
    line_num: u32,
};

pub const WordIndex = struct {
    /// word → hits
    index: std.StringHashMap(std.ArrayList(WordHit)),
    /// path → set of words contributed (for efficient re-index cleanup).
    /// WordIndex owns these path keys.
    file_words: std.StringHashMap([]const []const u8),
    allocator: std.mem.Allocator,
    /// Bulk builders can skip per-file term sets; incremental updates re-enable
    /// them after the immutable/bulk portion has been assembled.
    skip_file_words: bool = false,
    /// Whether each non-empty id_to_path entry owns its path allocation. This is
    /// independent of file_words tracking (bulk/mmap indexes own path strings,
    /// while normal mutable indexes alias file_words keys).
    owns_id_paths: bool = false,
    enabled: bool = true,
    path_to_id: std.StringHashMap(u32),
    id_to_path: std.ArrayList([]const u8),
    /// freed doc_id slots available for reuse by getOrCreateDocId
    free_ids: std.ArrayList(u32) = .empty,
    /// doc_id → number of tokens indexed for that doc (BM25 length normalization).
    doc_lengths: std.AutoHashMap(u32, u32),
    /// Sum of all values in doc_lengths.
    total_tokens: u64 = 0,
    /// Zero-copy read mode: when non-null, the postings live in this mmap'd
    /// word.index file and `index` is empty — search/searchPrefix binary-search
    /// the sorted on-disk words instead. The first write promotes to a heap
    /// index (promoteIfBorrowed). Cuts warm-daemon RSS from ~4x the file to a
    /// small word directory + touched pages.
    mmap_data: ?[]align(std.heap.page_size_min) const u8 = null,
    /// Byte offset of each sorted word record in mmap_data, for binary search.
    word_dir: []u32 = &.{},

    pub fn hitPath(self: *const WordIndex, hit: WordHit) []const u8 {
        if (hit.doc_id < self.id_to_path.items.len) return self.id_to_path.items[hit.doc_id];
        return "";
    }

    fn getOrCreateDocId(self: *WordIndex, path: []const u8) !u32 {
        if (self.path_to_id.get(path)) |id| return id;
        if (self.free_ids.items.len > 0) {
            const freed = self.free_ids.items[self.free_ids.items.len - 1];
            // put first: a failed put must leave the free list and slot untouched
            try self.path_to_id.put(path, freed);
            _ = self.free_ids.pop();
            self.id_to_path.items[@as(usize, freed)] = path;
            return freed;
        }
        const id: u32 = @intCast(self.id_to_path.items.len);
        try self.id_to_path.append(self.allocator, path);
        self.path_to_id.put(path, id) catch |err| {
            _ = self.id_to_path.pop();
            return err;
        };
        return id;
    }

    pub fn init(allocator: std.mem.Allocator) WordIndex {
        return .{
            .index = std.StringHashMap(std.ArrayList(WordHit)).init(allocator),
            .file_words = std.StringHashMap([]const []const u8).init(allocator),
            .allocator = allocator,
            .path_to_id = std.StringHashMap(u32).init(allocator),
            .id_to_path = .empty,
            .doc_lengths = std.AutoHashMap(u32, u32).init(allocator),
            .total_tokens = 0,
        };
    }

    pub fn deinit(self: *WordIndex) void {
        if (self.mmap_data) |m| {
            // Zero-copy mode: index/path_to_id/file_words are empty; id_to_path
            // owns the duped paths; word_dir + doc_lengths are heap; the postings
            // live in the mmap. Free the heap bits and unmap.
            self.index.deinit();
            self.path_to_id.deinit();
            self.file_words.deinit();
            for (self.id_to_path.items) |path| {
                if (path.len > 0) self.allocator.free(path);
            }
            self.id_to_path.deinit(self.allocator);
            self.free_ids.deinit(self.allocator);
            self.doc_lengths.deinit();
            self.allocator.free(self.word_dir);
            cio.munmap(m);
            return;
        }
        // Free hit lists and duped word keys
        var iter = self.index.iterator();
        while (iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.deinit(self.allocator);
        }
        self.index.deinit();

        // Free per-file word sets
        var fw_iter = self.file_words.iterator();
        while (fw_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.file_words.deinit();

        if (self.owns_id_paths) {
            for (self.id_to_path.items) |path| {
                if (path.len > 0) self.allocator.free(path);
            }
        }

        self.path_to_id.deinit();
        self.id_to_path.deinit(self.allocator);
        self.free_ids.deinit(self.allocator);
        self.doc_lengths.deinit();
    }

    /// Remove all index entries for a file (call before re-indexing).
    pub fn removeFile(self: *WordIndex, path: []const u8) void {
        if (self.mmap_data != null) {
            // Zero-copy mode: postings live in the mmap and a remove is a
            // write, so promote first — but only when the file is actually
            // tracked (id_to_path is the only populated map in this mode).
            var tracked = false;
            for (self.id_to_path.items) |p| {
                if (std.mem.eql(u8, p, path)) {
                    tracked = true;
                    break;
                }
            }
            if (!tracked) return;
            self.promoteIfBorrowed() catch return;
        }

        if (self.file_words.fetchRemove(path)) |removed| {
            const stable_path = removed.key;
            const words_slice = removed.value;

            const doc_id = self.path_to_id.get(stable_path) orelse {
                self.allocator.free(words_slice);
                self.allocator.free(stable_path);
                return;
            };
            _ = self.path_to_id.remove(stable_path);
            if (doc_id < self.id_to_path.items.len) {
                const old_path = self.id_to_path.items[doc_id];
                // Bulk/mmap modes give id_to_path its own strings; otherwise the
                // slot aliases stable_path, which is freed below.
                if (self.owns_id_paths and old_path.len > 0) self.allocator.free(old_path);
                self.id_to_path.items[doc_id] = "";
                self.free_ids.append(self.allocator, doc_id) catch {};
            }
            if (self.doc_lengths.fetchRemove(doc_id)) |kv| {
                self.total_tokens -= kv.value;
            }
            defer {
                self.allocator.free(words_slice);
                self.allocator.free(stable_path);
            }

            // For each word this file contributed, remove hits with this doc_id.
            // Prune empty buckets so churn does not leak key/list entries.
            for (words_slice) |word| {
                const word_ptr = &word;
                if (self.index.getEntry(word_ptr.*)) |entry| {
                    const hits = entry.value_ptr;
                    var i: usize = 0;
                    while (i < hits.items.len) {
                        if (hits.items[i].doc_id == doc_id) {
                            _ = hits.swapRemove(i);
                        } else {
                            i += 1;
                        }
                    }
                    if (hits.items.len == 0) {
                        const owned_word = entry.key_ptr.*;
                        hits.deinit(self.allocator);
                        _ = self.index.remove(word_ptr.*);
                        self.allocator.free(owned_word);
                    }
                }
            }
            return;
        }

        // No per-file word list: the file came from a bulk path (disk
        // fast-load, sharded cold scan), where removeFile used to be a silent
        // no-op that left every stale posting behind. Sweep all posting lists
        // for the doc_id instead; the next indexFile gives the file a word
        // list, so this runs at most once per file.
        const doc_id = self.path_to_id.get(path) orelse return;
        _ = self.path_to_id.remove(path);
        if (self.doc_lengths.fetchRemove(doc_id)) |kv| {
            self.total_tokens -= kv.value;
        }
        if (doc_id < self.id_to_path.items.len) {
            const old_path = self.id_to_path.items[doc_id];
            if (self.owns_id_paths and old_path.len > 0) self.allocator.free(old_path);
            self.id_to_path.items[doc_id] = "";
            self.free_ids.append(self.allocator, doc_id) catch {};
        }
        var empty_words: std.ArrayList([]const u8) = .empty;
        defer empty_words.deinit(self.allocator);
        var it = self.index.iterator();
        while (it.next()) |entry| {
            const hits = entry.value_ptr;
            var i: usize = 0;
            while (i < hits.items.len) {
                if (hits.items[i].doc_id == doc_id) {
                    _ = hits.swapRemove(i);
                } else {
                    i += 1;
                }
            }
            if (hits.items.len == 0) {
                empty_words.append(self.allocator, entry.key_ptr.*) catch continue;
            }
        }
        for (empty_words.items) |word| {
            if (self.index.fetchRemove(word)) |kv| {
                var hits = kv.value;
                hits.deinit(self.allocator);
                self.allocator.free(kv.key);
            }
        }
    }
    fn indexOneToken(
        self: *WordIndex,
        token: []const u8,
        doc_id: u32,
        line_num: u32,
        words_set: ?*std.StringHashMap(void),
    ) !void {
        const gop = try self.index.getOrPut(token);
        if (!gop.found_existing) {
            // A failed dupe must take the fresh entry with it — the key still
            // points at the tokenizer's stack buffer and the value is
            // undefined; left in place, the next insert that lands on it
            // dereferences garbage.
            const duped = self.allocator.dupe(u8, token) catch |err| {
                _ = self.index.remove(token);
                return err;
            };
            gop.key_ptr.* = duped;
            gop.value_ptr.* = .empty;
        }
        if (gop.value_ptr.items.len > 0) {
            const last = gop.value_ptr.items[gop.value_ptr.items.len - 1];
            if (last.doc_id == doc_id and last.line_num == line_num) {
                if (words_set) |set| {
                    const wgop = try set.getOrPut(gop.key_ptr.*);
                    if (!wgop.found_existing) wgop.key_ptr.* = gop.key_ptr.*;
                }
                return;
            }
        }
        try gop.value_ptr.append(self.allocator, .{
            .doc_id = doc_id,
            .line_num = line_num,
        });
        if (words_set) |set| {
            const wgop = try set.getOrPut(gop.key_ptr.*);
            if (!wgop.found_existing) wgop.key_ptr.* = gop.key_ptr.*;
        }
    }

    pub fn indexFile(self: *WordIndex, path: []const u8, content: []const u8) !void {
        if (!self.enabled) return;
        // A write to a zero-copy (mmap) index must first materialize a heap index.
        try self.promoteIfBorrowed();
        // Clean up old entries first; removeFile guarantees the path is no
        // longer tracked, so the stable copy is always a fresh dupe.
        self.removeFile(path);
        if (self.skip_file_words) self.owns_id_paths = true;

        const stable_path = try self.allocator.dupe(u8, path);
        errdefer self.allocator.free(stable_path);

        const doc_id = try self.getOrCreateDocId(stable_path);

        // Use page_allocator-backed arena for words_set — pages are returned
        // to the OS immediately when the arena is deinitialized, instead of
        // being retained by the GPA (which caused ~1GB of page retention
        // across 14K files of alloc/free churn).
        var words_arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
        defer words_arena.deinit();
        var words_set = std.StringHashMap(void).init(words_arena.allocator());
        const tracked_words: ?*std.StringHashMap(void) = if (self.skip_file_words) null else &words_set;
        var line_num: u32 = 0;
        var lines = std.mem.splitScalar(u8, content, '\n');
        var doc_token_count: u32 = 0;

        while (lines.next()) |line| {
            line_num += 1;
            var tok = WordTokenizer{ .buf = line };
            while (tok.next()) |word| {
                if (word.len < 2) continue;
                doc_token_count +|= 1;

                const aa = words_arena.allocator();

                // Fast path: lowercase into a stack buffer (avoids one alloc per word).
                // Most identifiers fit in 256 bytes; rare longer ones fall through
                // to the arena path.
                var stack_buf: [256]u8 = undefined;
                const lower_word: []const u8 = if (word.len <= stack_buf.len) blk: {
                    for (word, 0..) |c, j| stack_buf[j] = normalizeChar(c);
                    // Check if the lowercase form differs from the original;
                    // if identical (already lowercase) and word is the actual
                    // source token, we can use `word` directly — but we'd need
                    // the string to outlive the stack frame when stored, so
                    // dup only at the insert-key boundary below.
                    break :blk stack_buf[0..word.len];
                } else blk: {
                    const buf = aa.alloc(u8, word.len) catch continue;
                    for (word, 0..) |c, j| buf[j] = normalizeChar(c);
                    break :blk buf;
                };

                // Index the lowercase form.
                try indexOneToken(self, lower_word, doc_id, line_num, tracked_words);

                // Sub-tokens from identifier splitting (camelCase, snake_case, etc.).
                // Skip the alloc'd ArrayList when the word is too short or all-lower
                // (no split possible).
                var needs_split: bool = false;
                if (word.len >= 4) {
                    for (word) |c| {
                        if (c == '_' or (c >= 'A' and c <= 'Z')) {
                            needs_split = true;
                            break;
                        }
                    }
                }
                if (needs_split) {
                    var sub_toks: std.ArrayList([]const u8) = .empty;
                    defer sub_toks.deinit(aa);
                    splitIdentifier(word, &sub_toks, aa) catch continue;
                    for (sub_toks.items) |sub| {
                        try indexOneToken(self, sub, doc_id, line_num, tracked_words);
                    }
                }
            }
        }

        // Per-file word lists make subsequent removeFile O(file). Cold worker
        // shards skip them entirely; merged/mmap paths fall back to one index
        // sweep on the first update, after which incremental files are tracked.
        if (!self.skip_file_words) {
            const fw_key = if (self.owns_id_paths)
                try self.allocator.dupe(u8, stable_path)
            else
                stable_path;
            errdefer if (self.owns_id_paths) self.allocator.free(fw_key);
            const compact = try self.allocator.alloc([]const u8, words_set.count());
            errdefer self.allocator.free(compact);
            var ki: usize = 0;
            var wk_iter = words_set.keyIterator();
            while (wk_iter.next()) |k| : (ki += 1) {
                compact[ki] = k.*;
            }
            try self.file_words.put(fw_key, compact);
        }
        words_set.deinit();

        if (self.doc_lengths.get(doc_id)) |old_len| {
            self.total_tokens -%= old_len;
        }
        try self.doc_lengths.put(doc_id, doc_token_count);
        self.total_tokens += doc_token_count;
    }

    /// Fold a shard (a WordIndex built in parallel over a disjoint, contiguous
    /// set of documents) into self. The shard's local doc_ids [0, shard.len)
    /// are remapped to global ids [base, base + shard.len), where base is self's
    /// current doc count — so merging shards in worker order reproduces the exact
    /// doc_id assignment of the serial (single-worker) path. Keys/paths are
    /// re-duped into self.allocator since the shard is arena-backed and freed
    /// after merge. Postings stay doc_id-ascending (shard lists are ascending and
    /// each shard's global range follows the previous one). See the per-worker
    /// shard build in watcher.initialScanWithWorkerCount.
    pub fn mergeShard(self: *WordIndex, shard: *WordIndex) !void {
        std.debug.assert(self.id_to_path.items.len == 0 or self.owns_id_paths);
        const base: u32 = @intCast(self.id_to_path.items.len);
        self.owns_id_paths = true;

        // Paths + per-doc lengths. Roll each document back transactionally: the
        // old ordering freed `duped` after a later map failure while id_to_path
        // still referenced it, leaving a dangling pointer/double-free hazard.
        for (shard.id_to_path.items, 0..) |path, local| {
            const global_id: u32 = base + @as(u32, @intCast(local));
            const duped = try self.allocator.dupe(u8, path);
            errdefer self.allocator.free(duped);
            try self.id_to_path.append(self.allocator, duped);
            errdefer _ = self.id_to_path.pop();
            try self.path_to_id.put(duped, global_id);
            errdefer _ = self.path_to_id.remove(duped);
            if (shard.doc_lengths.get(@intCast(local))) |len| {
                try self.doc_lengths.put(global_id, len);
            }
        }

        // Postings: append each shard term's hits with doc_id offset by base.
        var it = shard.index.iterator();
        while (it.next()) |entry| {
            const term = entry.key_ptr.*;
            const shard_hits = entry.value_ptr.items;
            const gop = try self.index.getOrPut(term);
            if (!gop.found_existing) {
                // A failed dupe must take the fresh entry with it — the key
                // still points at the shard's arena, freed after the merge.
                const dterm = self.allocator.dupe(u8, term) catch |err| {
                    _ = self.index.remove(term);
                    return err;
                };
                gop.key_ptr.* = dterm;
                gop.value_ptr.* = .empty;
            }
            try gop.value_ptr.ensureUnusedCapacity(self.allocator, shard_hits.len);
            for (shard_hits) |h| {
                gop.value_ptr.appendAssumeCapacity(.{ .doc_id = base + h.doc_id, .line_num = h.line_num });
            }
        }

        self.total_tokens += shard.total_tokens;
    }

    /// Look up all hits for a word. O(1) lookup + O(hits) iteration.
    /// Query is normalized to lowercase (all index keys are stored lowercase).
    pub fn search(self: *WordIndex, word: []const u8) []align(1) const WordHit {
        var buf: [512]u8 = undefined;
        const lower = if (word.len <= buf.len) blk: {
            for (word, 0..) |c, i| buf[i] = normalizeChar(c);
            break :blk buf[0..word.len];
        } else word;
        if (self.mmap_data != null) return self.mmapSearch(lower);
        if (self.index.get(lower)) |hits| return hits.items;
        return &.{};
    }

    /// Binary-search the sorted on-disk words; return the postings as a
    /// zero-copy slice into the mmap. Unaligned (records sit at arbitrary byte
    /// offsets), hence align(1) — fields are read with unaligned loads.
    fn mmapSearch(self: *WordIndex, lower: []const u8) []align(1) const WordHit {
        const data = self.mmap_data.?;
        var lo: usize = 0;
        var hi: usize = self.word_dir.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const off = self.word_dir[mid];
            const wlen = std.mem.readInt(u16, data[off..][0..2], .little);
            const wbytes = data[off + 2 ..][0..wlen];
            switch (std.mem.order(u8, wbytes, lower)) {
                .lt => lo = mid + 1,
                .gt => hi = mid,
                .eq => {
                    const hc_off = off + 2 + wlen;
                    const hit_count = std.mem.readInt(u32, data[hc_off..][0..4], .little);
                    const posts = data[hc_off + 4 ..][0 .. @as(usize, hit_count) * @sizeOf(WordHit)];
                    return std.mem.bytesAsSlice(WordHit, posts);
                },
            }
        }
        return &.{};
    }

    /// First write to a zero-copy (mmap) index rebuilds a heap index from the
    /// mmap so the mutation has somewhere to land, then unmaps. Reads stay
    /// zero-copy; only an actual edit pays this one-time cost.
    fn promoteIfBorrowed(self: *WordIndex) !void {
        const data = self.mmap_data orelse return;
        var new_index = std.StringHashMap(std.ArrayList(WordHit)).init(self.allocator);
        errdefer {
            var it = new_index.iterator();
            while (it.next()) |e| {
                self.allocator.free(e.key_ptr.*);
                e.value_ptr.deinit(self.allocator);
            }
            new_index.deinit();
        }
        try new_index.ensureTotalCapacity(@intCast(self.word_dir.len));
        for (self.word_dir) |off| {
            const wlen = std.mem.readInt(u16, data[off..][0..2], .little);
            const word = try self.allocator.dupe(u8, data[off + 2 ..][0..wlen]);
            errdefer self.allocator.free(word);
            const hc_off = off + 2 + wlen;
            const hit_count = std.mem.readInt(u32, data[hc_off..][0..4], .little);
            const posts = std.mem.bytesAsSlice(WordHit, data[hc_off + 4 ..][0 .. @as(usize, hit_count) * @sizeOf(WordHit)]);
            var list: std.ArrayList(WordHit) = .empty;
            errdefer list.deinit(self.allocator);
            try list.appendUnalignedSlice(self.allocator, posts);
            try new_index.put(word, list);
        }
        var new_p2i = std.StringHashMap(u32).init(self.allocator);
        errdefer new_p2i.deinit();
        try new_p2i.ensureTotalCapacity(@intCast(self.id_to_path.items.len));
        for (self.id_to_path.items, 0..) |p, i| {
            if (p.len > 0) try new_p2i.put(p, @intCast(i));
        }
        // Commit: drop the (empty) mmap-mode maps + unmap, install heap maps.
        self.index.deinit();
        self.path_to_id.deinit();
        self.allocator.free(self.word_dir);
        cio.munmap(data);
        self.index = new_index;
        self.path_to_id = new_p2i;
        self.word_dir = &.{};
        self.mmap_data = null;
    }

    /// Look up hits, returning results allocated by the caller.
    /// Deduplicates by (path, line_num).
    pub fn searchDeduped(self: *WordIndex, word: []const u8, allocator: std.mem.Allocator) ![]const WordHit {
        const hits = self.search(word);
        if (hits.len == 0) return try allocator.alloc(WordHit, 0);
        if (hits.len == 1) {
            var out = try allocator.alloc(WordHit, 1);
            out[0] = hits[0];
            return out;
        }

        const DedupKey = struct { doc_id: u32, line_num: u32 };
        var seen = std.AutoHashMap(DedupKey, void).init(allocator);
        defer seen.deinit();
        try seen.ensureTotalCapacity(@intCast(hits.len));

        var result: std.ArrayList(WordHit) = .empty;
        errdefer result.deinit(allocator);
        try result.ensureTotalCapacity(allocator, hits.len);

        for (hits) |hit| {
            const key = DedupKey{ .doc_id = hit.doc_id, .line_num = hit.line_num };
            const gop = try seen.getOrPut(key);
            if (!gop.found_existing) {
                result.appendAssumeCapacity(hit);
            }
        }
        return result.toOwnedSlice(allocator);
    }

    /// Collect all hits for index keys that begin with `prefix_raw` (normalized internally to
    /// lowercase). Only keys strictly longer than the normalized prefix are considered —
    /// exact-match keys are already handled by Tier 0 (`search`).
    /// Results are deduplicated by (doc_id, line_num), capped at `max_results`, and returned as an owned slice.
    pub fn searchPrefix(self: *WordIndex, prefix_raw: []const u8, allocator: std.mem.Allocator, max_results: usize) ![]const WordHit {
        if (prefix_raw.len == 0 or max_results == 0) return try allocator.alloc(WordHit, 0);
        var buf: [512]u8 = undefined;
        const prefix = if (prefix_raw.len <= buf.len) blk: {
            for (prefix_raw, 0..) |c, i| buf[i] = normalizeChar(c);
            break :blk buf[0..prefix_raw.len];
        } else prefix_raw;

        var result: std.ArrayList(WordHit) = .empty;
        errdefer result.deinit(allocator);
        try result.ensureTotalCapacity(allocator, max_results);
        const DedupKey = struct { doc_id: u32, line_num: u32 };
        var seen = std.AutoHashMap(DedupKey, void).init(allocator);
        defer seen.deinit();
        try seen.ensureTotalCapacity(@intCast(max_results));

        if (self.mmap_data) |data| {
            // Sorted on-disk words: binary-search the prefix lower bound, then
            // walk forward while the word still starts with `prefix`.
            var lo: usize = 0;
            var hi: usize = self.word_dir.len;
            while (lo < hi) {
                const mid = lo + (hi - lo) / 2;
                const off = self.word_dir[mid];
                const wlen = std.mem.readInt(u16, data[off..][0..2], .little);
                if (std.mem.order(u8, data[off + 2 ..][0..wlen], prefix) == .lt) lo = mid + 1 else hi = mid;
            }
            var wi = lo;
            outer_mmap: while (wi < self.word_dir.len) : (wi += 1) {
                const off = self.word_dir[wi];
                const wlen = std.mem.readInt(u16, data[off..][0..2], .little);
                const wbytes = data[off + 2 ..][0..wlen];
                if (!std.mem.startsWith(u8, wbytes, prefix)) break; // past the prefix range
                if (wlen <= prefix.len) continue; // strictly longer; exact is Tier 0
                const hc_off = off + 2 + wlen;
                const hit_count = std.mem.readInt(u32, data[hc_off..][0..4], .little);
                const posts = std.mem.bytesAsSlice(WordHit, data[hc_off + 4 ..][0 .. @as(usize, hit_count) * @sizeOf(WordHit)]);
                for (posts) |hit| {
                    const dk = DedupKey{ .doc_id = hit.doc_id, .line_num = hit.line_num };
                    const gop = try seen.getOrPut(dk);
                    if (!gop.found_existing) {
                        result.appendAssumeCapacity(hit);
                        if (result.items.len >= max_results) break :outer_mmap;
                    }
                }
            }
            return result.toOwnedSlice(allocator);
        }
        var key_iter = self.index.keyIterator();
        outer: while (key_iter.next()) |k| {
            if (k.len <= prefix.len) continue; // strictly longer: exact match is Tier 0
            if (!std.mem.startsWith(u8, k.*, prefix)) continue;
            const hits = self.index.get(k.*) orelse continue;
            for (hits.items) |hit| {
                const dk = DedupKey{ .doc_id = hit.doc_id, .line_num = hit.line_num };
                const gop = try seen.getOrPut(dk);
                if (!gop.found_existing) {
                    result.appendAssumeCapacity(hit);
                    if (result.items.len >= max_results) break :outer;
                }
            }
        }
        return result.toOwnedSlice(allocator);
    }

    pub fn fileCount(self: *WordIndex) u32 {
        return @intCast(self.file_words.count());
    }

    /// BM25 helper: number of docs the ranker can see (source of truth regardless of skip_file_words).
    pub fn rankedDocCount(self: *const WordIndex) u32 {
        return @intCast(self.doc_lengths.count());
    }

    /// BM25 helper: number of indexed tokens in a doc, or 0 if unknown.
    pub fn docLength(self: *const WordIndex, doc_id: u32) u32 {
        return self.doc_lengths.get(doc_id) orelse 0;
    }

    /// BM25 helper: average doc length over docs that have a recorded length.
    /// Returns 1.0 when no docs are tracked, so callers can divide safely.
    pub fn avgDocLength(self: *const WordIndex) f32 {
        const n = self.doc_lengths.count();
        if (n == 0) return 1.0;
        const avg = @as(f32, @floatFromInt(self.total_tokens)) / @as(f32, @floatFromInt(n));
        return if (avg > 0) avg else 1.0;
    }

    /// Shrink all hit lists and per-file word sets to release excess capacity.
    pub fn shrinkAllocations(self: *WordIndex) void {
        var iter = self.index.iterator();
        while (iter.next()) |entry| {
            if (entry.value_ptr.capacity > entry.value_ptr.items.len) {
                entry.value_ptr.shrinkAndFree(self.allocator, entry.value_ptr.items.len);
            }
        }
    }

    pub const DiskHeader = struct {
        file_count: u32,
        git_head: ?[40]u8,
    };

    const DISK_MAGIC = [4]u8{ 'C', 'D', 'B', 'W' };
    const DISK_FORMAT_VERSION: u16 = 3;

    pub fn writeToDisk(self: *WordIndex, io: std.Io, dir_path: []const u8, git_head: ?[40]u8) !void {
        var file_table: std.ArrayList([]const u8) = .empty;
        defer file_table.deinit(self.allocator);
        const doc_to_disk = try self.allocator.alloc(u32, self.id_to_path.items.len);
        defer self.allocator.free(doc_to_disk);
        @memset(doc_to_disk, std.math.maxInt(u32));

        // id_to_path is the doc table and always complete; file_words only
        // covers incrementally indexed files once bulk-loaded docs exist.
        for (self.id_to_path.items, 0..) |path, doc_idx| {
            if (path.len == 0) continue;
            if (path.len > std.math.maxInt(u16)) return error.NameTooLong;
            const id: u32 = @intCast(file_table.items.len);
            try file_table.append(self.allocator, path);
            doc_to_disk[doc_idx] = id;
        }

        var words_sorted: std.ArrayList([]const u8) = .empty;
        defer words_sorted.deinit(self.allocator);
        try words_sorted.ensureTotalCapacity(self.allocator, self.index.count());
        var word_iter = self.index.keyIterator();
        while (word_iter.next()) |word_ptr| {
            if (word_ptr.*.len > std.math.maxInt(u16)) return error.NameTooLong;
            words_sorted.appendAssumeCapacity(word_ptr.*);
        }
        std.mem.sort([]const u8, words_sorted.items, {}, struct {
            fn lt(_: void, a: []const u8, b: []const u8) bool {
                return std.mem.order(u8, a, b) == .lt;
            }
        }.lt);

        const rand_suffix = cio.randU64();
        const tmp_path = try std.fmt.allocPrint(self.allocator, "{s}/word.index.{x}.tmp", .{ dir_path, rand_suffix });
        defer self.allocator.free(tmp_path);
        const final_path = try std.fmt.allocPrint(self.allocator, "{s}/word.index", .{dir_path});
        defer self.allocator.free(final_path);

        const file = try std.Io.Dir.cwd().createFile(io, tmp_path, .{});
        defer file.close(io);

        var file_buf: [256 * 1024]u8 = undefined;
        var writer = file.writer(io, &file_buf);

        var header_buf: [51]u8 = [_]u8{0} ** 51;
        @memcpy(header_buf[0..4], &DISK_MAGIC);
        std.mem.writeInt(u16, header_buf[4..6], DISK_FORMAT_VERSION, .little);
        std.mem.writeInt(u32, header_buf[6..10], @intCast(file_table.items.len), .little);
        if (git_head) |head| {
            header_buf[10] = 40;
            @memcpy(header_buf[11..51], &head);
        }
        try writer.interface.writeAll(&header_buf);

        for (file_table.items) |path| {
            var pl_buf: [2]u8 = undefined;
            std.mem.writeInt(u16, &pl_buf, @intCast(path.len), .little);
            try writer.interface.writeAll(&pl_buf);
            try writer.interface.writeAll(path);
        }

        var wc_buf: [4]u8 = undefined;
        std.mem.writeInt(u32, &wc_buf, @intCast(words_sorted.items.len), .little);
        try writer.interface.writeAll(&wc_buf);

        for (words_sorted.items) |word| {
            const hits = self.index.get(word) orelse return error.InvalidData;
            var wl_buf: [2]u8 = undefined;
            std.mem.writeInt(u16, &wl_buf, @intCast(word.len), .little);
            try writer.interface.writeAll(&wl_buf);
            try writer.interface.writeAll(word);

            var hc_buf: [4]u8 = undefined;
            std.mem.writeInt(u32, &hc_buf, @intCast(hits.items.len), .little);
            try writer.interface.writeAll(&hc_buf);
            // doc_id → disk_id is a pure integer remap (path_to_id keeps
            // paths unique, so every live doc has exactly one disk id).
            // The old per-hit StringHashMap lookup wyhashed the full path
            // string for every posting — the dominant CPU term of the whole
            // persist on large repos (#475's 840ms). Hits are also batched
            // into 4KB chunks instead of one 8-byte writeAll each.
            var chunk: [4096]u8 = undefined;
            var chunk_len: usize = 0;
            for (hits.items) |hit| {
                const file_id = doc_to_disk[hit.doc_id];
                if (file_id == std.math.maxInt(u32)) return error.InvalidData;
                std.mem.writeInt(u32, chunk[chunk_len..][0..4], file_id, .little);
                std.mem.writeInt(u32, chunk[chunk_len + 4 ..][0..4], hit.line_num, .little);
                chunk_len += 8;
                if (chunk_len == chunk.len) {
                    try writer.interface.writeAll(chunk[0..chunk_len]);
                    chunk_len = 0;
                }
            }
            if (chunk_len > 0) try writer.interface.writeAll(chunk[0..chunk_len]);
        }

        // v3 trailer: per-doc length table for BM25.
        // file_id (u32 disk-id) → length (u32). Total tokens follows as u64.
        var dl_count_buf: [4]u8 = undefined;
        std.mem.writeInt(u32, &dl_count_buf, @intCast(file_table.items.len), .little);
        try writer.interface.writeAll(&dl_count_buf);
        for (file_table.items) |path| {
            const in_mem_id = self.path_to_id.get(path) orelse {
                var z: [4]u8 = .{ 0, 0, 0, 0 };
                try writer.interface.writeAll(&z);
                continue;
            };
            const len = self.doc_lengths.get(in_mem_id) orelse 0;
            var lb: [4]u8 = undefined;
            std.mem.writeInt(u32, &lb, len, .little);
            try writer.interface.writeAll(&lb);
        }
        var tt_buf: [8]u8 = undefined;
        std.mem.writeInt(u64, &tt_buf, self.total_tokens, .little);
        try writer.interface.writeAll(&tt_buf);

        try writer.interface.flush();

        try std.Io.Dir.cwd().rename(tmp_path, std.Io.Dir.cwd(), final_path, io);
    }

    pub fn readFromDisk(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) ?WordIndex {
        return readFromDiskInner(io, dir_path, allocator) catch null;
    }

    fn readFromDiskInner(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?WordIndex {
        const index_path = try std.fmt.allocPrint(allocator, "{s}/word.index", .{dir_path});
        defer allocator.free(index_path);

        const data = std.Io.Dir.cwd().readFileAlloc(io, index_path, allocator, .limited(512 * 1024 * 1024)) catch return null;
        defer allocator.free(data);

        if (data.len < 51) return null;
        if (!std.mem.eql(u8, data[0..4], &DISK_MAGIC)) return null;
        const version = std.mem.readInt(u16, data[4..6], .little);
        if (version != DISK_FORMAT_VERSION) return null;
        const file_count = std.mem.readInt(u32, data[6..10], .little);

        var file_paths = try allocator.alloc([]u8, file_count);
        defer allocator.free(file_paths);
        const used_paths = try allocator.alloc(bool, file_count);
        defer allocator.free(used_paths);
        @memset(used_paths, false);
        var parsed_files: u32 = 0;
        defer {
            for (0..parsed_files) |i| {
                if (!used_paths[i]) allocator.free(file_paths[i]);
            }
        }

        var pos: usize = 51;
        for (0..file_count) |i| {
            if (pos + 2 > data.len) return null;
            const path_len = std.mem.readInt(u16, data[pos..][0..2], .little);
            pos += 2;
            if (path_len == 0 or pos + path_len > data.len) return null;
            file_paths[i] = try allocator.dupe(u8, data[pos .. pos + path_len]);
            pos += path_len;
            parsed_files += 1;
        }

        if (pos + 4 > data.len) return null;
        const word_count = std.mem.readInt(u32, data[pos..][0..4], .little);
        pos += 4;

        var result = WordIndex.init(allocator);
        errdefer result.deinit();

        // Pre-size the maps to the exact counts so they don't overshoot via
        // incremental doubling while loading (saves tens of MB on big indexes).
        try result.index.ensureTotalCapacity(word_count);
        try result.path_to_id.ensureTotalCapacity(file_count);
        try result.doc_lengths.ensureTotalCapacity(file_count);

        for (0..word_count) |_| {
            if (pos + 2 > data.len) return null;
            const word_len = std.mem.readInt(u16, data[pos..][0..2], .little);
            pos += 2;
            if (word_len == 0 or pos + word_len > data.len) return null;
            const word = try allocator.dupe(u8, data[pos .. pos + word_len]);
            pos += word_len;
            errdefer allocator.free(word);

            if (pos + 4 > data.len) return null;
            const hit_count = std.mem.readInt(u32, data[pos..][0..4], .little);
            pos += 4;

            var hits: std.ArrayList(WordHit) = .empty;
            errdefer hits.deinit(allocator);
            try hits.ensureTotalCapacity(allocator, hit_count);

            for (0..hit_count) |_| {
                if (pos + 8 > data.len) return null;
                const file_id = std.mem.readInt(u32, data[pos..][0..4], .little);
                pos += 4;
                if (file_id >= file_count) return null;
                const line_num = std.mem.readInt(u32, data[pos..][0..4], .little);
                pos += 4;
                hits.appendAssumeCapacity(.{ .doc_id = file_id, .line_num = line_num });
            }

            const gop = try result.index.getOrPut(word);
            if (gop.found_existing) return error.InvalidData;
            gop.key_ptr.* = word;
            gop.value_ptr.* = hits;
        }

        // v3 trailer: per-doc length table.
        if (pos + 4 > data.len) return null;
        const dl_count = std.mem.readInt(u32, data[pos..][0..4], .little);
        pos += 4;
        if (dl_count != file_count) return null;
        if (pos + dl_count * 4 + 8 > data.len) return null;
        var dl_values = try allocator.alloc(u32, dl_count);
        defer allocator.free(dl_values);
        for (0..dl_count) |i| {
            dl_values[i] = std.mem.readInt(u32, data[pos..][0..4], .little);
            pos += 4;
        }
        const total_tokens_loaded = std.mem.readInt(u64, data[pos..][0..8], .little);
        pos += 8;

        if (pos != data.len) return null;

        // Populate path_to_id and id_to_path from file_paths
        try result.id_to_path.ensureTotalCapacity(allocator, file_count);
        for (0..file_count) |i| {
            result.id_to_path.appendAssumeCapacity(file_paths[i]);
            try result.path_to_id.put(file_paths[i], @intCast(i));
            if (dl_values[i] > 0) {
                try result.doc_lengths.put(@intCast(i), dl_values[i]);
            }
        }
        result.total_tokens = total_tokens_loaded;

        // Loaded indexes have no file_words for their bulk documents, but future
        // incremental writes should track them. id_to_path owns the loaded path
        // strings independently of that tracking policy.
        @memset(used_paths, true);
        result.owns_id_paths = true;

        return result;
    }

    /// Zero-copy load: mmap the word.index file and build only a small word
    /// directory + doc-length table; postings stay in the mmap. Returns a
    /// WordIndex in zero-copy mode (first write promotes to heap). Null on any
    /// malformation — caller can fall back to readFromDisk.
    pub fn mmapFromDisk(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) ?WordIndex {
        return mmapFromDiskInner(io, dir_path, allocator) catch null;
    }

    fn mmapFromDiskInner(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?WordIndex {
        const index_path = try std.fmt.allocPrint(allocator, "{s}/word.index", .{dir_path});
        defer allocator.free(index_path);

        const file = std.Io.Dir.cwd().openFile(io, index_path, .{}) catch return null;
        defer file.close(io);
        const size = file.length(io) catch return null;
        if (size < 51) return null;
        const data = cio.mmapReadonly(file.handle, size) catch return null;
        errdefer cio.munmap(data);

        if (!std.mem.eql(u8, data[0..4], &DISK_MAGIC)) return null;
        if (std.mem.readInt(u16, data[4..6], .little) != DISK_FORMAT_VERSION) return null;
        const file_count = std.mem.readInt(u32, data[6..10], .little);

        var result = WordIndex.init(allocator);
        result.owns_id_paths = true;
        // mmap_data stays null until the hand-off below, so this errdefer takes
        // the heap deinit path (frees the duped paths); word_dir + mmap have
        // their own errdefers.
        errdefer result.deinit();

        try result.id_to_path.ensureTotalCapacity(allocator, file_count);
        var pos: usize = 51;
        for (0..file_count) |_| {
            if (pos + 2 > data.len) return null;
            const plen = std.mem.readInt(u16, data[pos..][0..2], .little);
            pos += 2;
            if (plen == 0 or pos + plen > data.len) return null;
            const path = try allocator.dupe(u8, data[pos .. pos + plen]);
            result.id_to_path.appendAssumeCapacity(path);
            pos += plen;
        }

        if (pos + 4 > data.len) return null;
        const word_count = std.mem.readInt(u32, data[pos..][0..4], .little);
        pos += 4;
        const word_dir = try allocator.alloc(u32, word_count);
        errdefer allocator.free(word_dir);
        for (0..word_count) |i| {
            if (pos + 2 > data.len) return null;
            word_dir[i] = @intCast(pos);
            const wlen = std.mem.readInt(u16, data[pos..][0..2], .little);
            pos += 2 + wlen;
            if (pos + 4 > data.len) return null;
            const hit_count = std.mem.readInt(u32, data[pos..][0..4], .little);
            pos += 4 + @as(usize, hit_count) * @sizeOf(WordHit);
            if (pos > data.len) return null;
        }

        if (pos + 4 > data.len) return null;
        const dl_count = std.mem.readInt(u32, data[pos..][0..4], .little);
        pos += 4;
        if (dl_count != file_count or pos + @as(usize, dl_count) * 4 + 8 > data.len) return null;
        for (0..dl_count) |i| {
            const len = std.mem.readInt(u32, data[pos..][0..4], .little);
            pos += 4;
            if (len > 0) try result.doc_lengths.put(@intCast(i), len);
        }
        result.total_tokens = std.mem.readInt(u64, data[pos..][0..8], .little);
        pos += 8;
        if (pos != data.len) return null;

        // Hand off: switch to zero-copy mode. result.deinit now takes the mmap path.
        result.mmap_data = data;
        result.word_dir = word_dir;
        return result;
    }
    pub fn readDiskHeader(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?DiskHeader {
        const index_path = try std.fmt.allocPrint(allocator, "{s}/word.index", .{dir_path});
        defer allocator.free(index_path);

        const file = std.Io.Dir.cwd().openFile(io, index_path, .{}) catch return null;
        defer file.close(io);

        var buf: [51]u8 = undefined;
        const n = file.readPositionalAll(io, &buf, 0) catch return null;
        if (n < 51) return null;
        if (!std.mem.eql(u8, buf[0..4], &DISK_MAGIC)) return null;
        const version = std.mem.readInt(u16, buf[4..6], .little);
        if (version < 1 or version > DISK_FORMAT_VERSION) return null;

        const file_count = std.mem.readInt(u32, buf[6..10], .little);
        var git_head: ?[40]u8 = null;
        if (buf[10] == 40) {
            var head: [40]u8 = undefined;
            @memcpy(&head, buf[11..51]);
            git_head = head;
        }
        return DiskHeader{
            .file_count = file_count,
            .git_head = git_head,
        };
    }

    pub fn readGitHead(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?[40]u8 {
        const header = try readDiskHeader(io, dir_path, allocator) orelse return null;
        return header.git_head;
    }
};

// ── Trigram index ───────────────────────────────────────────
// Maps 3-byte sequences → set of file paths.
// Enables fast substring search: extract trigrams from query,
// intersect candidate file sets, then verify with actual match.

pub const Trigram = u24;

pub fn packTrigram(a: u8, b: u8, c: u8) Trigram {
    return @as(Trigram, a) << 16 | @as(Trigram, b) << 8 | @as(Trigram, c);
}

pub const PostingMask = struct {
    next_mask: u8 = 0, // bloom filter of chars following this trigram
    loc_mask: u8 = 0, // bit mask of (position % 8) where trigram appears
};

pub const DocPosting = struct {
    doc_id: u32,
    next_mask: u8 = 0,
    loc_mask: u8 = 0,
};

pub const PostingList = struct {
    items: std.ArrayList(DocPosting) = .empty,
    path_to_id: ?*const std.StringHashMap(u32) = null,

    pub fn deinit(self: *PostingList, allocator: std.mem.Allocator) void {
        self.items.deinit(allocator);
    }

    pub fn count(self: *const PostingList) usize {
        return self.items.items.len;
    }

    pub fn get(self: *const PostingList, path: []const u8) ?PostingMask {
        const p2id = self.path_to_id orelse return null;
        const doc_id = p2id.get(path) orelse return null;
        return self.getByDocId(doc_id);
    }

    pub fn contains(self: *const PostingList, path: []const u8) bool {
        return self.get(path) != null;
    }

    pub fn getByDocId(self: *const PostingList, doc_id: u32) ?PostingMask {
        // Binary search on sorted doc_id array
        const items = self.items.items;
        var lo: usize = 0;
        var hi: usize = items.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (items[mid].doc_id == doc_id) return PostingMask{ .next_mask = items[mid].next_mask, .loc_mask = items[mid].loc_mask };
            if (items[mid].doc_id < doc_id) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return null;
    }

    pub fn containsDocId(self: *const PostingList, doc_id: u32) bool {
        const items = self.items.items;
        var lo: usize = 0;
        var hi: usize = items.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (items[mid].doc_id == doc_id) return true;
            if (items[mid].doc_id < doc_id) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return false;
    }
    pub fn getOrAddPosting(self: *PostingList, allocator: std.mem.Allocator, doc_id: u32) !*DocPosting {
        // Binary search for existing
        const items = self.items.items;
        var lo: usize = 0;
        var hi: usize = items.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (items[mid].doc_id == doc_id) return &self.items.items[mid];
            if (items[mid].doc_id < doc_id) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        // Insert at sorted position
        try self.items.insert(allocator, lo, .{ .doc_id = doc_id });
        return &self.items.items[lo];
    }

    pub fn removeDocId(self: *PostingList, doc_id: u32) void {
        var lo: usize = 0;
        var hi: usize = self.items.items.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (self.items.items[mid].doc_id < doc_id) {
                lo = mid + 1;
            } else if (self.items.items[mid].doc_id > doc_id) {
                hi = mid;
            } else {
                _ = self.items.orderedRemove(mid);
                return;
            }
        }
    }
};

pub const TrigramIndex = struct {
    /// trigram → posting list with doc IDs
    index: std.AutoHashMap(Trigram, PostingList),
    /// path → list of trigrams contributed (for cleanup)
    file_trigrams: std.StringHashMap(std.ArrayList(Trigram)),
    /// path → doc_id mapping
    path_to_id: std.StringHashMap(u32),
    /// doc_id → path mapping (may contain "" sentinels for freed slots)
    id_to_path: std.ArrayList([]const u8),
    /// freed doc_id slots available for reuse by getOrCreateDocId
    free_ids: std.ArrayList(u32),
    allocator: std.mem.Allocator,
    /// When true, deinit frees the path keys in file_trigrams (set by readFromDisk).
    owns_paths: bool = false,

    /// Maximum entries per posting list — caps memory for common trigrams.
    /// Trigrams appearing in more files than this are poor discriminators anyway.
    const MAX_POSTINGS: usize = 256;

    pub fn init(allocator: std.mem.Allocator) TrigramIndex {
        return .{
            .index = std.AutoHashMap(Trigram, PostingList).init(allocator),
            .file_trigrams = std.StringHashMap(std.ArrayList(Trigram)).init(allocator),
            .path_to_id = std.StringHashMap(u32).init(allocator),
            .id_to_path = .empty,
            .free_ids = .empty,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *TrigramIndex) void {
        var iter = self.index.iterator();
        while (iter.next()) |entry| {
            entry.value_ptr.deinit(self.allocator);
        }
        self.index.deinit();

        var ft_iter = self.file_trigrams.iterator();
        while (ft_iter.next()) |entry| {
            entry.value_ptr.deinit(self.allocator);
        }
        self.file_trigrams.deinit();

        // When owns_paths=true, paths were dup'd in getOrCreateDocId and stored
        // in id_to_path. Free them here from id_to_path (not file_trigrams),
        // because lean code paths like insertBulkNew never populate file_trigrams,
        // and removeFile clears file_trigrams entries before deinit can see them.
        // id_to_path is the single source of truth for owned path memory.
        // Tombstone slots (empty strings from removeFile) are skipped.
        if (self.owns_paths) {
            for (self.id_to_path.items) |p| {
                if (p.len > 0) self.allocator.free(p);
            }
        }

        self.path_to_id.deinit();
        self.id_to_path.deinit(self.allocator);
        self.free_ids.deinit(self.allocator);
    }

    fn getOrCreateDocId(self: *TrigramIndex, path: []const u8) !u32 {
        if (self.path_to_id.get(path)) |id| return id;
        // owns_paths=true stores a dup so callers can free their source memory.
        const stored_path: []const u8 = if (self.owns_paths)
            try self.allocator.dupe(u8, path)
        else
            path;
        errdefer if (self.owns_paths) self.allocator.free(stored_path);
        const id: u32 = if (self.free_ids.items.len > 0) blk: {
            const freed: u32 = self.free_ids.pop() orelse unreachable;
            self.id_to_path.items[@as(usize, freed)] = stored_path;
            break :blk freed;
        } else blk: {
            const new_id: u32 = @intCast(self.id_to_path.items.len);
            try self.id_to_path.append(self.allocator, stored_path);
            break :blk new_id;
        };
        try self.path_to_id.put(stored_path, id);
        return id;
    }

    pub fn removeFile(self: *TrigramIndex, path: []const u8) void {
        const doc_id = self.path_to_id.get(path) orelse {
            const trigrams = self.file_trigrams.getPtr(path) orelse return;
            trigrams.deinit(self.allocator);
            _ = self.file_trigrams.remove(path);
            return;
        };
        // Always clean path_to_id first, regardless of whether file_trigrams has an entry.
        _ = self.path_to_id.remove(path);
        // Free the doc_id slot for reuse on next indexFile call.
        self.free_ids.append(self.allocator, doc_id) catch {};
        if (self.file_trigrams.getPtr(path)) |trigrams| {
            for (trigrams.items) |tri| {
                if (self.index.getPtr(tri)) |posting_list| {
                    posting_list.removeDocId(doc_id);
                    if (posting_list.items.items.len == 0) {
                        posting_list.deinit(self.allocator);
                        _ = self.index.remove(tri);
                    }
                }
            }
            trigrams.deinit(self.allocator);
            _ = self.file_trigrams.remove(path);
        }
        const old_path = self.id_to_path.items[doc_id];
        if (self.owns_paths and old_path.len > 0) self.allocator.free(old_path);
        self.id_to_path.items[doc_id] = "";
    }

    pub fn indexFile(self: *TrigramIndex, path: []const u8, content: []const u8) !void {
        const id_count_before = self.id_to_path.items.len;
        self.removeFile(path);

        const doc_id = try self.getOrCreateDocId(path);
        // If id_to_path grew, this is a brand-new file (doc_id == max), so append
        // maintains sorted PostingList order.  If it did not grow, a freed slot was
        // reused and we must use sorted insert to preserve the invariant.
        const is_new_doc = self.id_to_path.items.len > id_count_before;

        // Phase 1: accumulate masks locally per trigram (no global index writes)
        var local = std.AutoHashMap(Trigram, PostingMask).init(self.allocator);
        defer local.deinit();
        // Pre-size: a file typically has ~content.len/4 unique trigrams
        const estimated_unique = @max(@as(u32, 64), @as(u32, @intCast(@min(content.len / 4, 65536))));
        local.ensureTotalCapacity(estimated_unique) catch {};

        if (content.len >= 3) {
            for (0..content.len - 2) |i| {
                // Skip trigrams that are pure whitespace (terrible filters, ~12% of all occurrences)
                const c0 = content[i];
                const c1 = content[i + 1];
                const c2 = content[i + 2];
                if ((c0 == ' ' or c0 == '\t' or c0 == '\n' or c0 == '\r') and
                    (c1 == ' ' or c1 == '\t' or c1 == '\n' or c1 == '\r') and
                    (c2 == ' ' or c2 == '\t' or c2 == '\n' or c2 == '\r')) continue;

                const tri = packTrigram(
                    normalizeChar(c0),
                    normalizeChar(c1),
                    normalizeChar(c2),
                );
                const gop = try local.getOrPut(tri);
                if (!gop.found_existing) {
                    gop.value_ptr.* = PostingMask{};
                }
                gop.value_ptr.loc_mask |= @as(u8, 1) << @intCast(i % 8);
                if (i + 3 < content.len) {
                    gop.value_ptr.next_mask |= @as(u8, 1) << @intCast(normalizeChar(content[i + 3]) % 8);
                }
            }
        }

        // Phase 2: bulk-insert one posting per trigram into global index
        var tri_list: std.ArrayList(Trigram) = .empty;
        errdefer tri_list.deinit(self.allocator);

        var local_iter = local.iterator();
        while (local_iter.next()) |entry| {
            const tri = entry.key_ptr.*;
            const mask = entry.value_ptr.*;

            const idx_gop = try self.index.getOrPut(tri);
            if (!idx_gop.found_existing) {
                idx_gop.value_ptr.* = .{ .path_to_id = &self.path_to_id };
            }
            if (is_new_doc) {
                // New doc_id is always max: append maintains sorted PostingList order.
                try idx_gop.value_ptr.items.append(self.allocator, .{
                    .doc_id = doc_id,
                    .next_mask = mask.next_mask,
                    .loc_mask = mask.loc_mask,
                });
            } else {
                // Reused doc_id: sorted insert to maintain PostingList binary-search invariant.
                const posting = try idx_gop.value_ptr.getOrAddPosting(self.allocator, doc_id);
                posting.next_mask = mask.next_mask;
                posting.loc_mask = mask.loc_mask;
            }

            try tri_list.append(self.allocator, tri);
        }
        const stable_path = self.id_to_path.items[doc_id];
        try self.file_trigrams.put(stable_path, tri_list);
    }

    /// Like indexFile but reuses a caller-provided local HashMap to avoid alloc/free per file.
    pub fn indexFileReuse(self: *TrigramIndex, path: []const u8, content: []const u8, local: *std.AutoHashMap(Trigram, PostingMask)) !void {
        const id_count_before = self.id_to_path.items.len;
        self.removeFile(path);
        const doc_id = try self.getOrCreateDocId(path);
        const is_new_doc = self.id_to_path.items.len > id_count_before;

        // Phase 1: accumulate masks in reusable local map
        local.clearRetainingCapacity();
        if (content.len >= 3) {
            for (0..content.len - 2) |i| {
                const c0 = content[i];
                const c1 = content[i + 1];
                const c2 = content[i + 2];
                if ((c0 == ' ' or c0 == '\t' or c0 == '\n' or c0 == '\r') and
                    (c1 == ' ' or c1 == '\t' or c1 == '\n' or c1 == '\r') and
                    (c2 == ' ' or c2 == '\t' or c2 == '\n' or c2 == '\r')) continue;
                const tri = packTrigram(normalizeChar(c0), normalizeChar(c1), normalizeChar(c2));
                const gop = try local.getOrPut(tri);
                if (!gop.found_existing) gop.value_ptr.* = PostingMask{};
                gop.value_ptr.loc_mask |= @as(u8, 1) << @intCast(i % 8);
                if (i + 3 < content.len) {
                    gop.value_ptr.next_mask |= @as(u8, 1) << @intCast(normalizeChar(content[i + 3]) % 8);
                }
            }
        }

        // Phase 2: bulk-insert
        var tri_list: std.ArrayList(Trigram) = .empty;
        errdefer tri_list.deinit(self.allocator);
        var local_iter = local.iterator();
        while (local_iter.next()) |entry| {
            const tri = entry.key_ptr.*;
            const mask = entry.value_ptr.*;
            const idx_gop = try self.index.getOrPut(tri);
            if (!idx_gop.found_existing) {
                idx_gop.value_ptr.* = .{ .path_to_id = &self.path_to_id };
            }
            if (is_new_doc) {
                try idx_gop.value_ptr.items.append(self.allocator, .{
                    .doc_id = doc_id,
                    .next_mask = mask.next_mask,
                    .loc_mask = mask.loc_mask,
                });
            } else {
                const posting = try idx_gop.value_ptr.getOrAddPosting(self.allocator, doc_id);
                posting.next_mask = mask.next_mask;
                posting.loc_mask = mask.loc_mask;
            }
            try tri_list.append(self.allocator, tri);
        }
        try self.file_trigrams.put(path, tri_list);
    }

    /// Extract trigrams from content — thread-safe, no shared state.
    pub fn extractTrigrams(content: []const u8, alloc: std.mem.Allocator) std.AutoHashMap(Trigram, PostingMask) {
        var local = std.AutoHashMap(Trigram, PostingMask).init(alloc);
        const estimated = @max(@as(u32, 64), @as(u32, @intCast(@min(content.len / 4, 65536))));
        local.ensureTotalCapacity(estimated) catch {};
        if (content.len >= 3) {
            for (0..content.len - 2) |i| {
                const c0 = content[i];
                const c1 = content[i + 1];
                const c2 = content[i + 2];
                if ((c0 == ' ' or c0 == '\t' or c0 == '\n' or c0 == '\r') and
                    (c1 == ' ' or c1 == '\t' or c1 == '\n' or c1 == '\r') and
                    (c2 == ' ' or c2 == '\t' or c2 == '\n' or c2 == '\r')) continue;
                const tri = packTrigram(normalizeChar(c0), normalizeChar(c1), normalizeChar(c2));
                const gop = local.getOrPut(tri) catch continue;
                if (!gop.found_existing) gop.value_ptr.* = PostingMask{};
                gop.value_ptr.loc_mask |= @as(u8, 1) << @intCast(i % 8);
                if (i + 3 < content.len) {
                    gop.value_ptr.next_mask |= @as(u8, 1) << @intCast(normalizeChar(content[i + 3]) % 8);
                }
            }
        }
        return local;
    }

    /// Insert pre-extracted trigrams. NOT thread-safe.
    pub fn insertExtracted(self: *TrigramIndex, path: []const u8, local: *std.AutoHashMap(Trigram, PostingMask)) !void {
        self.removeFile(path);
        const doc_id = try self.getOrCreateDocId(path);
        var tri_list: std.ArrayList(Trigram) = .empty;
        errdefer tri_list.deinit(self.allocator);
        var iter = local.iterator();
        while (iter.next()) |entry| {
            const tri = entry.key_ptr.*;
            const mask = entry.value_ptr.*;
            const idx_gop = try self.index.getOrPut(tri);
            if (!idx_gop.found_existing) {
                idx_gop.value_ptr.* = .{ .path_to_id = &self.path_to_id };
            }
            try idx_gop.value_ptr.items.append(self.allocator, .{
                .doc_id = doc_id,
                .next_mask = mask.next_mask,
                .loc_mask = mask.loc_mask,
            });
            try tri_list.append(self.allocator, tri);
        }
        try self.file_trigrams.put(path, tri_list);
    }

    pub const BulkEntry = struct { tri: Trigram, mask: PostingMask };

    /// Lean bulk insert for cold builds: no removeFile, no file_trigrams tracking.
    /// Assumes doc_id is always new (strictly increasing), so uses simple append.
    pub fn insertBulkNew(self: *TrigramIndex, path: []const u8, trigrams: []const BulkEntry) !void {
        const doc_id = try self.getOrCreateDocId(path);
        for (trigrams) |te| {
            const idx_gop = try self.index.getOrPut(te.tri);
            if (!idx_gop.found_existing) {
                idx_gop.value_ptr.* = .{ .path_to_id = &self.path_to_id };
            }
            try idx_gop.value_ptr.items.append(self.allocator, .{
                .doc_id = doc_id,
                .next_mask = te.mask.next_mask,
                .loc_mask = te.mask.loc_mask,
            });
        }
    }

    /// Bulk-insert directly from the worker's reusable extraction map. This
    /// avoids materializing a second per-file trigram array before insertion.
    pub fn insertBulkMapNew(self: *TrigramIndex, path: []const u8, trigrams: *std.AutoHashMap(Trigram, PostingMask)) !void {
        const doc_id = try self.getOrCreateDocId(path);
        var iter = trigrams.iterator();
        while (iter.next()) |entry| {
            const idx_gop = try self.index.getOrPut(entry.key_ptr.*);
            if (!idx_gop.found_existing) {
                idx_gop.value_ptr.* = .{ .path_to_id = &self.path_to_id };
            }
            try idx_gop.value_ptr.items.append(self.allocator, .{
                .doc_id = doc_id,
                .next_mask = entry.value_ptr.next_mask,
                .loc_mask = entry.value_ptr.loc_mask,
            });
        }
    }

    /// Merge a cold-build shard whose local document IDs start at zero. Shards
    /// are merged in source-file order, so offsetting each posting by `base`
    /// preserves the sorted-posting invariant. New trigram lists are moved
    /// without copying; overlapping lists append one contiguous shard slice.
    pub fn mergeBulkShard(self: *TrigramIndex, shard: *TrigramIndex) !void {
        std.debug.assert(self.owns_paths);
        std.debug.assert(self.free_ids.items.len == 0);
        std.debug.assert(shard.free_ids.items.len == 0);

        const base: u32 = @intCast(self.id_to_path.items.len);
        try self.id_to_path.ensureUnusedCapacity(self.allocator, shard.id_to_path.items.len);
        try self.path_to_id.ensureUnusedCapacity(@intCast(shard.id_to_path.items.len));
        for (shard.id_to_path.items, 0..) |path, local_id| {
            const duped = try self.allocator.dupe(u8, path);
            errdefer self.allocator.free(duped);
            self.id_to_path.appendAssumeCapacity(duped);
            errdefer _ = self.id_to_path.pop();
            try self.path_to_id.put(duped, base + @as(u32, @intCast(local_id)));
            errdefer _ = self.path_to_id.remove(duped);
        }

        const can_transfer = self.allocator.ptr == shard.allocator.ptr and
            self.allocator.vtable == shard.allocator.vtable;
        var iter = shard.index.iterator();
        while (iter.next()) |entry| {
            for (entry.value_ptr.items.items) |*posting| posting.doc_id += base;

            const gop = try self.index.getOrPut(entry.key_ptr.*);
            if (!gop.found_existing) {
                gop.value_ptr.* = .{ .path_to_id = &self.path_to_id };
                if (can_transfer) {
                    gop.value_ptr.items = entry.value_ptr.items;
                    entry.value_ptr.items = .empty;
                    continue;
                }
            }
            try gop.value_ptr.items.appendSlice(self.allocator, entry.value_ptr.items.items);
        }
    }

    /// Find candidate files that contain ALL trigrams from the query.
    pub fn candidates(self: *TrigramIndex, query: []const u8, allocator: std.mem.Allocator) ?[]const []const u8 {
        if (query.len < 3) return null;

        const tri_count = query.len - 2;

        var unique = std.AutoHashMap(Trigram, void).init(allocator);
        defer unique.deinit();
        unique.ensureTotalCapacity(@intCast(tri_count)) catch return null;
        for (0..tri_count) |i| {
            const tri = packTrigram(
                normalizeChar(query[i]),
                normalizeChar(query[i + 1]),
                normalizeChar(query[i + 2]),
            );
            _ = unique.getOrPut(tri) catch return null;
        }

        var sets: std.ArrayList(*PostingList) = .empty;
        defer sets.deinit(allocator);
        sets.ensureTotalCapacity(allocator, unique.count()) catch return null;

        var tri_iter = unique.keyIterator();
        while (tri_iter.next()) |tri_ptr| {
            const posting_list = self.index.getPtr(tri_ptr.*) orelse {
                return allocator.alloc([]const u8, 0) catch null;
            };
            sets.appendAssumeCapacity(posting_list);
        }

        if (sets.items.len == 0) {
            return allocator.alloc([]const u8, 0) catch null;
        }

        // Sort posting lists by size (smallest first) for efficient intersection
        std.mem.sort(*PostingList, sets.items, {}, struct {
            fn lt(_: void, a: *PostingList, b: *PostingList) bool {
                return a.items.items.len < b.items.items.len;
            }
        }.lt);

        // Sorted merge intersection: start with smallest list's doc_ids
        var result_ids: std.ArrayList(u32) = .empty;
        defer result_ids.deinit(allocator);

        // Seed with doc_ids from smallest posting list
        result_ids.ensureTotalCapacity(allocator, sets.items[0].items.items.len) catch return null;
        for (sets.items[0].items.items) |p| {
            result_ids.appendAssumeCapacity(p.doc_id);
        }

        // Intersect with each subsequent list (both sorted → merge O(n+m))
        for (sets.items[1..]) |set| {
            var write: usize = 0;
            var si: usize = 0;
            const set_items = set.items.items;
            for (result_ids.items) |id| {
                // Advance set pointer to >= id
                while (si < set_items.len and set_items[si].doc_id < id) : (si += 1) {}
                if (si < set_items.len and set_items[si].doc_id == id) {
                    result_ids.items[write] = id;
                    write += 1;
                    si += 1;
                }
            }
            result_ids.items.len = write;
            if (write == 0) break; // early exit if intersection is empty
        }

        // Bloom-filter refinement. Hoist the per-consecutive-pair trigram packing
        // and posting-list hash probes out of the per-candidate loop — they depend
        // only on the query, not on doc_id — leaving just the two getByDocId binary
        // searches per candidate. Result set is bit-identical to the inline version.
        const Pair = struct { list_a: ?*PostingList, list_b: ?*PostingList, next_bit: u8 };
        var pairs: []Pair = &.{};
        defer if (pairs.len > 0) allocator.free(pairs);
        if (tri_count >= 2) {
            pairs = allocator.alloc(Pair, tri_count - 1) catch return null;
            for (pairs, 0..) |*pair, j| {
                pair.* = .{
                    .list_a = self.index.getPtr(packTrigram(normalizeChar(query[j]), normalizeChar(query[j + 1]), normalizeChar(query[j + 2]))),
                    .list_b = self.index.getPtr(packTrigram(normalizeChar(query[j + 1]), normalizeChar(query[j + 2]), normalizeChar(query[j + 3]))),
                    .next_bit = @as(u8, 1) << @intCast(normalizeChar(query[j + 3]) % 8),
                };
            }
        }

        var result: std.ArrayList([]const u8) = .empty;
        errdefer result.deinit(allocator);
        result.ensureTotalCapacity(allocator, result_ids.items.len) catch return null;

        next_cand: for (result_ids.items) |doc_id| {
            for (pairs) |pair| {
                const list_a = pair.list_a orelse continue;
                const list_b = pair.list_b orelse continue;
                const mask_a = list_a.getByDocId(doc_id) orelse continue;
                const mask_b = list_b.getByDocId(doc_id) orelse continue;

                if ((mask_a.next_mask & pair.next_bit) == 0) continue :next_cand;

                const rotated = (mask_a.loc_mask << 1) | (mask_a.loc_mask >> 7);
                if ((rotated & mask_b.loc_mask) == 0) continue :next_cand;
            }

            if (doc_id < self.id_to_path.items.len) {
                result.appendAssumeCapacity(self.id_to_path.items[doc_id]);
            }
        }

        return result.toOwnedSlice(allocator) catch {
            result.deinit(allocator);
            return null;
        };
    }

    pub fn candidatesRegex(self: *TrigramIndex, query: *const RegexQuery, allocator: std.mem.Allocator) ?[]const []const u8 {
        if (query.and_trigrams.len == 0 and query.or_groups.len == 0) return null;

        var result_set: ?std.AutoHashMap(u32, void) = null;
        defer if (result_set) |*rs| rs.deinit();

        if (query.and_trigrams.len > 0) {
            for (query.and_trigrams) |tri| {
                const posting_list = self.index.getPtr(tri) orelse {
                    var empty = allocator.alloc([]const u8, 0) catch return null;
                    _ = &empty;
                    return allocator.alloc([]const u8, 0) catch null;
                };
                if (result_set == null) {
                    result_set = std.AutoHashMap(u32, void).init(allocator);
                    for (posting_list.items.items) |p| {
                        result_set.?.put(p.doc_id, {}) catch return null;
                    }
                } else {
                    var to_remove: std.ArrayList(u32) = .empty;
                    defer to_remove.deinit(allocator);
                    var it = result_set.?.keyIterator();
                    while (it.next()) |key| {
                        if (!posting_list.containsDocId(key.*)) {
                            to_remove.append(allocator, key.*) catch return null;
                        }
                    }
                    for (to_remove.items) |key| {
                        _ = result_set.?.remove(key);
                    }
                }
            }
        }

        for (query.or_groups) |group| {
            if (group.len == 0) continue;

            var union_set = std.AutoHashMap(u32, void).init(allocator);
            defer union_set.deinit();
            for (group) |tri| {
                const posting_list = self.index.getPtr(tri) orelse continue;
                for (posting_list.items.items) |p| {
                    union_set.put(p.doc_id, {}) catch return null;
                }
            }

            if (result_set == null) {
                result_set = std.AutoHashMap(u32, void).init(allocator);
                var it = union_set.keyIterator();
                while (it.next()) |key| {
                    result_set.?.put(key.*, {}) catch return null;
                }
            } else {
                var to_remove: std.ArrayList(u32) = .empty;
                defer to_remove.deinit(allocator);
                var it = result_set.?.keyIterator();
                while (it.next()) |key| {
                    if (!union_set.contains(key.*)) {
                        to_remove.append(allocator, key.*) catch return null;
                    }
                }
                for (to_remove.items) |key| {
                    _ = result_set.?.remove(key);
                }
            }
        }

        if (result_set == null) return null;

        var result: std.ArrayList([]const u8) = .empty;
        errdefer result.deinit(allocator);
        result.ensureTotalCapacity(allocator, result_set.?.count()) catch return null;
        var it = result_set.?.keyIterator();
        while (it.next()) |id_ptr| {
            const doc_id = id_ptr.*;
            if (doc_id < self.id_to_path.items.len) {
                result.appendAssumeCapacity(self.id_to_path.items[doc_id]);
            }
        }
        return result.toOwnedSlice(allocator) catch {
            result.deinit(allocator);
            return null;
        };
    }

    // ── Disk persistence ────────────────────────────────────

    pub const POSTINGS_MAGIC = [4]u8{ 'C', 'D', 'B', 'T' };
    pub const LOOKUP_MAGIC = [4]u8{ 'C', 'D', 'B', 'L' };
    pub const FORMAT_VERSION: u16 = 3;

    /// Posting entry for v3+: file_id (u32) + next_mask (u8) + loc_mask (u8) + pad (2 bytes) = 8 bytes
    pub const DiskPosting = extern struct {
        file_id: u32,
        next_mask: u8,
        loc_mask: u8,
        _pad: [2]u8 = .{ 0, 0 },
    };

    /// Posting entry for v1/v2 files: file_id (u16) + next_mask (u8) + loc_mask (u8) = 4 bytes
    pub const OldDiskPosting = extern struct {
        file_id: u16,
        next_mask: u8,
        loc_mask: u8,
    };

    /// Lookup entry: trigram (u32 low 24 bits) + offset (u32) + count (u32) = 12 bytes
    pub const LookupEntry = extern struct {
        trigram: u32,
        offset: u32,
        count: u32,
    };

    /// Write the current in-memory index to disk in a two-file format.
    /// Files are written atomically (write to tmp, then rename).
    pub fn writeToDisk(self: *TrigramIndex, io: std.Io, dir_path: []const u8, git_head: ?[40]u8) !void {
        // Step 1: Build file table from path_to_id (reuse existing doc IDs for consistency)
        var file_table: std.ArrayList([]const u8) = .empty;
        defer file_table.deinit(self.allocator);
        var disk_path_to_id = std.StringHashMap(u32).init(self.allocator);
        defer disk_path_to_id.deinit();

        if (self.file_trigrams.count() > 0) {
            var ft_iter = self.file_trigrams.keyIterator();
            while (ft_iter.next()) |path_ptr| {
                const id: u32 = @intCast(file_table.items.len);
                try file_table.append(self.allocator, path_ptr.*);
                try disk_path_to_id.put(path_ptr.*, id);
            }
        } else {
            for (self.id_to_path.items) |path| {
                if (path.len == 0) continue;
                const id: u32 = @intCast(file_table.items.len);
                try file_table.append(self.allocator, path);
                try disk_path_to_id.put(path, id);
            }
        }

        // Precompute doc_id -> disk file_id ONCE (one path hash per doc), so the
        // Step-3 posting loop does an array load instead of hashing the full path
        // string per posting (tens of millions of times on a large repo). Mirrors
        // the WordIndex doc_to_disk fix (#475).
        const doc_to_disk = try self.allocator.alloc(u32, self.id_to_path.items.len);
        defer self.allocator.free(doc_to_disk);
        @memset(doc_to_disk, std.math.maxInt(u32));
        for (self.id_to_path.items, 0..) |path, doc_idx| {
            if (path.len == 0) continue;
            doc_to_disk[doc_idx] = disk_path_to_id.get(path) orelse std.math.maxInt(u32);
        }

        const file_count: u32 = @intCast(file_table.items.len);

        // Step 2: Collect all trigrams, sort them, serialize postings contiguously
        var trigrams_sorted: std.ArrayList(Trigram) = .empty;
        defer trigrams_sorted.deinit(self.allocator);
        {
            var tri_iter = self.index.keyIterator();
            while (tri_iter.next()) |tri_ptr| {
                try trigrams_sorted.append(self.allocator, tri_ptr.*);
            }
        }
        std.mem.sort(Trigram, trigrams_sorted.items, {}, struct {
            fn lt(_: void, a: Trigram, b: Trigram) bool {
                return a < b;
            }
        }.lt);

        // Step 3: Build postings blob and lookup entries
        var postings_buf: std.ArrayList(DiskPosting) = .empty;
        defer postings_buf.deinit(self.allocator);
        var lookup_entries: std.ArrayList(LookupEntry) = .empty;
        defer lookup_entries.deinit(self.allocator);

        for (trigrams_sorted.items) |tri| {
            const posting_list = self.index.getPtr(tri) orelse continue;
            const offset: u32 = @intCast(postings_buf.items.len);
            var count: u32 = 0;
            for (posting_list.items.items) |p| {
                // Map in-memory doc_id to disk file_id via the precomputed array.
                if (p.doc_id >= doc_to_disk.len) continue;
                const fid = doc_to_disk[p.doc_id];
                if (fid == std.math.maxInt(u32)) continue;
                try postings_buf.append(self.allocator, .{
                    .file_id = fid,
                    .next_mask = p.next_mask,
                    .loc_mask = p.loc_mask,
                });
                count += 1;
            }
            try lookup_entries.append(self.allocator, .{
                .trigram = @as(u32, tri),
                .offset = offset,
                .count = count,
            });
        }

        // Step 4: Write postings file atomically (random suffix prevents collisions)
        const post_rand: u64 = cio.randU64();
        const postings_tmp = try std.fmt.allocPrint(self.allocator, "{s}/trigram.postings.{x}.tmp", .{ dir_path, post_rand });
        defer self.allocator.free(postings_tmp);
        const postings_final = try std.fmt.allocPrint(self.allocator, "{s}/trigram.postings", .{dir_path});
        defer self.allocator.free(postings_final);

        {
            const file = try std.Io.Dir.cwd().createFile(io, postings_tmp, .{});
            defer file.close(io);

            var pw_buf: [256 * 1024]u8 = undefined;
            var pw = file.writer(io, &pw_buf);

            // Header v3: magic(4) + version(2) + file_count(4) + head_len(1) + head(40) = 51 bytes
            try pw.interface.writeAll(&POSTINGS_MAGIC);
            var ver_buf: [2]u8 = undefined;
            std.mem.writeInt(u16, &ver_buf, FORMAT_VERSION, .little);
            try pw.interface.writeAll(&ver_buf);
            var fc_buf: [4]u8 = undefined;
            std.mem.writeInt(u32, &fc_buf, file_count, .little);
            try pw.interface.writeAll(&fc_buf);
            // Git HEAD: head_len (1 byte) + head (40 bytes)
            if (git_head) |head| {
                try pw.interface.writeAll(&.{40});
                try pw.interface.writeAll(&head);
            } else {
                try pw.interface.writeAll(&.{0});
                try pw.interface.writeAll(&([_]u8{0} ** 40));
            }

            // File table: for each file, path_len(u16) + path bytes
            for (file_table.items) |path| {
                var pl_buf: [2]u8 = undefined;
                std.mem.writeInt(u16, &pl_buf, @intCast(path.len), .little);
                try pw.interface.writeAll(&pl_buf);
                try pw.interface.writeAll(path);
            }

            // Postings data
            const postings_bytes = std.mem.sliceAsBytes(postings_buf.items);
            try pw.interface.writeAll(postings_bytes);
            try pw.interface.flush();
        }
        try std.Io.Dir.cwd().rename(postings_tmp, std.Io.Dir.cwd(), postings_final, io);

        // Step 5: Write lookup file atomically (random suffix prevents collisions)
        const lk_rand: u64 = cio.randU64();
        const lookup_tmp = try std.fmt.allocPrint(self.allocator, "{s}/trigram.lookup.{x}.tmp", .{ dir_path, lk_rand });
        defer self.allocator.free(lookup_tmp);
        const lookup_final = try std.fmt.allocPrint(self.allocator, "{s}/trigram.lookup", .{dir_path});
        defer self.allocator.free(lookup_final);

        {
            const file = try std.Io.Dir.cwd().createFile(io, lookup_tmp, .{});
            defer file.close(io);

            var lw_buf: [64 * 1024]u8 = undefined;
            var lw = file.writer(io, &lw_buf);

            // Header: magic(4) + version(2) + pad(2) + entry_count(4) = 12 bytes
            try lw.interface.writeAll(&LOOKUP_MAGIC);
            var ver_buf2: [2]u8 = undefined;
            std.mem.writeInt(u16, &ver_buf2, FORMAT_VERSION, .little);
            try lw.interface.writeAll(&ver_buf2);
            var pad_buf: [2]u8 = .{ 0, 0 };
            try lw.interface.writeAll(&pad_buf);
            var ec_buf: [4]u8 = undefined;
            std.mem.writeInt(u32, &ec_buf, @intCast(lookup_entries.items.len), .little);
            try lw.interface.writeAll(&ec_buf);

            // Entries (already aligned at 12 bytes each)
            const entry_bytes = std.mem.sliceAsBytes(lookup_entries.items);
            try lw.interface.writeAll(entry_bytes);
            try lw.interface.flush();
        }
        try std.Io.Dir.cwd().rename(lookup_tmp, std.Io.Dir.cwd(), lookup_final, io);
    }

    /// Load index from disk files into a fresh TrigramIndex.
    /// Returns null if files don't exist or are corrupt/stale.
    pub fn readFromDisk(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) ?TrigramIndex {
        return readFromDiskInner(io, dir_path, allocator) catch null;
    }

    fn readFromDiskInner(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?TrigramIndex {
        const postings_path = try std.fmt.allocPrint(allocator, "{s}/trigram.postings", .{dir_path});
        defer allocator.free(postings_path);
        const lookup_path = try std.fmt.allocPrint(allocator, "{s}/trigram.lookup", .{dir_path});
        defer allocator.free(lookup_path);

        // Read both files
        const postings_data = std.Io.Dir.cwd().readFileAlloc(io, postings_path, allocator, .limited(64 * 1024 * 1024)) catch return null;
        defer allocator.free(postings_data);
        const lookup_data = std.Io.Dir.cwd().readFileAlloc(io, lookup_path, allocator, .limited(64 * 1024 * 1024)) catch return null;
        defer allocator.free(lookup_data);

        // Validate postings header (v1: 8 bytes, v2: 49 bytes, v3: 51 bytes)
        if (postings_data.len < 8) return null;
        if (!std.mem.eql(u8, postings_data[0..4], &POSTINGS_MAGIC)) return null;
        const post_version = std.mem.readInt(u16, postings_data[4..6], .little);
        if (post_version < 1 or post_version > FORMAT_VERSION) return null;
        const file_count: u32 = if (post_version >= 3)
            std.mem.readInt(u32, postings_data[6..10], .little)
        else
            std.mem.readInt(u16, postings_data[6..8], .little);

        const file_table_start: usize = if (post_version >= 3) blk: {
            if (postings_data.len < 51) return null;
            break :blk 51;
        } else if (post_version >= 2) blk: {
            if (postings_data.len < 49) return null;
            break :blk 49;
        } else 8;

        // Parse file table
        var file_paths = try allocator.alloc([]u8, file_count);
        var parsed_files: u32 = 0;
        defer {
            for (0..parsed_files) |i| allocator.free(file_paths[i]);
            allocator.free(file_paths);
        }
        var pos: usize = file_table_start;
        for (0..file_count) |i| {
            if (pos + 2 > postings_data.len) return null;
            const path_len = std.mem.readInt(u16, postings_data[pos..][0..2], .little);
            pos += 2;
            if (pos + path_len > postings_data.len) return null;
            file_paths[i] = try allocator.dupe(u8, postings_data[pos .. pos + path_len]);
            parsed_files += 1;
            pos += path_len;
        }

        // Remaining bytes are DiskPosting entries
        const postings_start = pos;
        const postings_byte_len = postings_data.len - postings_start;
        const posting_size: usize = if (post_version >= 3) @sizeOf(DiskPosting) else @sizeOf(OldDiskPosting);
        if (postings_byte_len % posting_size != 0) return null;
        const total_postings = postings_byte_len / posting_size;

        // Validate lookup header
        if (lookup_data.len < 12) return null;
        if (!std.mem.eql(u8, lookup_data[0..4], &LOOKUP_MAGIC)) return null;
        const lk_version = std.mem.readInt(u16, lookup_data[4..6], .little);
        if (lk_version < 1 or lk_version > FORMAT_VERSION) return null;
        const entry_count = std.mem.readInt(u32, lookup_data[8..12], .little);
        if (lookup_data.len < 12 + entry_count * @sizeOf(LookupEntry)) return null;

        // Build in-memory index
        var result = TrigramIndex.init(allocator);
        result.owns_paths = true;
        errdefer result.deinit();

        // Allocate stable path strings owned by the index and build doc ID mappings
        var stable_paths = try allocator.alloc([]const u8, file_count);
        defer allocator.free(stable_paths);
        for (0..file_count) |i| {
            const duped = try allocator.dupe(u8, file_paths[i]);
            errdefer allocator.free(duped);
            stable_paths[i] = duped;
            try result.file_trigrams.put(duped, .empty);
            try result.path_to_id.put(duped, @intCast(i));
            try result.id_to_path.append(allocator, duped);
        }

        // Parse lookup entries and populate index + file_trigrams
        for (0..entry_count) |e| {
            const entry_off = 12 + e * @sizeOf(LookupEntry);
            const raw = lookup_data[entry_off..][0..@sizeOf(LookupEntry)];
            const entry: *align(1) const LookupEntry = @ptrCast(raw.ptr);

            const tri: Trigram = @intCast(entry.trigram);
            const p_off = entry.offset;
            const p_count = entry.count;

            if (@as(u64, p_off) + @as(u64, p_count) > @as(u64, total_postings)) return error.InvalidData;

            var posting_list: PostingList = .{ .path_to_id = &result.path_to_id };
            errdefer posting_list.deinit(allocator);

            for (0..p_count) |pi| {
                const pb_off = postings_start + (p_off + pi) * posting_size;
                const raw_posting = postings_data[pb_off..][0..posting_size];
                const file_id: u32 = if (post_version >= 3)
                    std.mem.readInt(u32, raw_posting[0..4], .little)
                else
                    std.mem.readInt(u16, raw_posting[0..2], .little);
                const next_mask = raw_posting[if (post_version >= 3) 4 else 2];
                const loc_mask = raw_posting[if (post_version >= 3) 5 else 3];

                if (file_id >= file_count) return error.InvalidData;

                const doc_id: u32 = file_id;
                const posting = try posting_list.getOrAddPosting(allocator, doc_id);
                posting.next_mask |= next_mask;
                posting.loc_mask |= loc_mask;

                // Track trigram in file_trigrams
                const path = stable_paths[file_id];
                if (result.file_trigrams.getPtr(path)) |tri_list| {
                    var found = false;
                    for (tri_list.items) |existing| {
                        if (existing == tri) {
                            found = true;
                            break;
                        }
                    }
                    if (!found) try tri_list.append(allocator, tri);
                }
            }

            try result.index.put(tri, posting_list);
        }

        return result;
    }

    /// Returns the number of indexed files (for staleness checks).
    pub fn fileCount(self: *const TrigramIndex) u32 {
        return @intCast(self.file_trigrams.count());
    }

    /// Shrink all posting lists to their actual length, releasing excess capacity.
    /// Call after bulk indexing to reclaim ArrayList over-allocation (~50% savings).
    pub fn shrinkPostingLists(self: *TrigramIndex) void {
        var iter = self.index.iterator();
        while (iter.next()) |entry| {
            if (entry.value_ptr.items.capacity > entry.value_ptr.items.items.len) {
                entry.value_ptr.items.shrinkAndFree(self.allocator, entry.value_ptr.items.items.len);
            }
        }
        // Also shrink file_trigrams lists
        var ft_iter = self.file_trigrams.iterator();
        while (ft_iter.next()) |entry| {
            if (entry.value_ptr.capacity > entry.value_ptr.items.len) {
                entry.value_ptr.shrinkAndFree(self.allocator, entry.value_ptr.items.len);
            }
        }
    }

    /// Header info that can be read without loading the full index.
    pub const DiskHeader = struct {
        file_count: u32,
        git_head: ?[40]u8,
    };

    /// Read just the postings file header — fast, no full file load.
    /// Returns null if the file doesn't exist or has an unrecognised format.
    pub fn readDiskHeader(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?DiskHeader {
        const postings_path = try std.fmt.allocPrint(allocator, "{s}/trigram.postings", .{dir_path});
        defer allocator.free(postings_path);

        const file = std.Io.Dir.cwd().openFile(io, postings_path, .{}) catch return null;
        defer file.close(io);

        var buf: [51]u8 = undefined;
        const n = file.readPositionalAll(io, &buf, 0) catch return null;
        if (n < 8) return null;
        if (!std.mem.eql(u8, buf[0..4], &POSTINGS_MAGIC)) return null;
        const version = std.mem.readInt(u16, buf[4..6], .little);
        if (version < 1 or version > FORMAT_VERSION) return null;
        const file_count: u32 = if (version >= 3)
            std.mem.readInt(u32, buf[6..10], .little)
        else
            std.mem.readInt(u16, buf[6..8], .little);

        var git_head: ?[40]u8 = null;
        if (version >= 3 and n >= 51) {
            const head_len = buf[10];
            if (head_len == 40) {
                var head: [40]u8 = undefined;
                @memcpy(&head, buf[11..51]);
                git_head = head;
            }
        } else if (version >= 2 and n >= 49) {
            const head_len = buf[8];
            if (head_len == 40) {
                var head: [40]u8 = undefined;
                @memcpy(&head, buf[9..49]);
                git_head = head;
            }
        }
        return DiskHeader{ .file_count = file_count, .git_head = git_head };
    }

    /// Read the git HEAD stored in the disk index header.
    /// Returns null if no git HEAD is stored or the file doesn't exist.
    pub fn readGitHead(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?[40]u8 {
        const header = try readDiskHeader(io, dir_path, allocator) orelse return null;
        return header.git_head;
    }
};

/// On-disk `status` metadata, readable WITHOUT loading the full index into
/// memory. #553: CLI `status` used to materialize the whole index (snapshot
/// mmap, or a full re-index + multi-GB snapshot rewrite when none existed)
/// before reading a few counts, so a backgrounded `codedb . status &` from a
/// SessionStart hook leaked a multi-GB resident orphan that stacked to OOM.
pub const StatusMeta = struct {
    indexed: bool,
    file_count: u32,
    git_head: ?[40]u8,
};

/// Read `status` metadata from the persisted trigram header alone — no Explorer,
/// no snapshot load, no re-index. Returns indexed=false when the project has no
/// persisted index so the caller reports "not indexed" instead of re-indexing.
pub fn readStatusMeta(io: std.Io, data_dir: []const u8, allocator: std.mem.Allocator) StatusMeta {
    const hdr = (TrigramIndex.readDiskHeader(io, data_dir, allocator) catch null) orelse
        return .{ .indexed = false, .file_count = 0, .git_head = null };
    return .{ .indexed = true, .file_count = hdr.file_count, .git_head = hdr.git_head };
}

// ── mmap-backed trigram index ───────────────────────────────
// Zero-copy: binary search on mmap'd lookup table, read postings directly.
// Replaces heap-based TrigramIndex after writeToDisk for O(log n) lookups
// with ~0 RSS (data lives in OS page cache).

pub const MmapTrigramIndex = struct {
    const mmap_align = std.heap.page_size_min;
    postings_data: []align(mmap_align) const u8,
    lookup_data: []align(mmap_align) const u8,
    file_table: []const []const u8,
    file_set: std.StringHashMap(void),
    postings_start: usize,
    lookup_entries: usize,
    post_version: u16,
    allocator: std.mem.Allocator,

    pub fn initFromDisk(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) ?MmapTrigramIndex {
        return initFromDiskInner(io, dir_path, allocator) catch null;
    }

    fn initFromDiskInner(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?MmapTrigramIndex {
        const postings_path = try std.fmt.allocPrint(allocator, "{s}/trigram.postings", .{dir_path});
        defer allocator.free(postings_path);
        const lookup_path = try std.fmt.allocPrint(allocator, "{s}/trigram.lookup", .{dir_path});
        defer allocator.free(lookup_path);

        // mmap postings file
        const post_file = std.Io.Dir.cwd().openFile(io, postings_path, .{}) catch return null;
        defer post_file.close(io);
        const post_size = post_file.length(io) catch return null;
        if (post_size < 8) return null;
        const postings_data = cio.mmapReadonly(post_file.handle, post_size) catch return null;
        errdefer cio.munmap(postings_data);

        // mmap lookup file
        const lk_file = std.Io.Dir.cwd().openFile(io, lookup_path, .{}) catch {
            cio.munmap(postings_data);
            return null;
        };
        defer lk_file.close(io);
        const lk_size = lk_file.length(io) catch {
            cio.munmap(postings_data);
            return null;
        };
        if (lk_size < 12) {
            cio.munmap(postings_data);
            return null;
        }
        const lookup_data = cio.mmapReadonly(lk_file.handle, lk_size) catch {
            cio.munmap(postings_data);
            return null;
        };
        errdefer cio.munmap(lookup_data);

        // Validate postings header
        if (!std.mem.eql(u8, postings_data[0..4], &TrigramIndex.POSTINGS_MAGIC)) return null;
        const post_version = std.mem.readInt(u16, postings_data[4..6], .little);
        if (post_version < 1 or post_version > TrigramIndex.FORMAT_VERSION) return null;
        const file_count: u32 = if (post_version >= 3)
            std.mem.readInt(u32, postings_data[6..10], .little)
        else
            std.mem.readInt(u16, postings_data[6..8], .little);

        const file_table_start: usize = if (post_version >= 3) blk: {
            if (postings_data.len < 51) return null;
            break :blk 51;
        } else if (post_version >= 2) blk: {
            if (postings_data.len < 49) return null;
            break :blk 49;
        } else 8;

        // Parse file table (we need owned path strings for lookups)
        var file_table = try allocator.alloc([]const u8, file_count);
        var parsed: u32 = 0;
        errdefer {
            for (0..parsed) |i| allocator.free(file_table[i]);
            allocator.free(file_table);
        }
        var pos: usize = file_table_start;
        for (0..file_count) |i| {
            if (pos + 2 > postings_data.len) return null;
            const path_len = std.mem.readInt(u16, postings_data[pos..][0..2], .little);
            pos += 2;
            if (pos + path_len > postings_data.len) return null;
            file_table[i] = try allocator.dupe(u8, postings_data[pos .. pos + path_len]);
            parsed += 1;
            pos += path_len;
        }

        // Build file_set for containsFile queries
        var file_set = std.StringHashMap(void).init(allocator);
        errdefer file_set.deinit();
        for (file_table[0..parsed]) |p| {
            try file_set.put(p, {});
        }

        const postings_start = pos;

        // Validate lookup header
        if (!std.mem.eql(u8, lookup_data[0..4], &TrigramIndex.LOOKUP_MAGIC)) return null;
        const lk_version = std.mem.readInt(u16, lookup_data[4..6], .little);
        if (lk_version < 1 or lk_version > TrigramIndex.FORMAT_VERSION) return null;
        const entry_count = std.mem.readInt(u32, lookup_data[8..12], .little);
        if (lookup_data.len < 12 + entry_count * @sizeOf(TrigramIndex.LookupEntry)) return null;

        return MmapTrigramIndex{
            .postings_data = postings_data,
            .lookup_data = lookup_data,
            .file_table = file_table,
            .file_set = file_set,
            .postings_start = postings_start,
            .lookup_entries = entry_count,
            .post_version = post_version,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *MmapTrigramIndex) void {
        for (self.file_table) |p| self.allocator.free(p);
        self.allocator.free(self.file_table);
        self.file_set.deinit();
        cio.munmap(self.postings_data);
        cio.munmap(self.lookup_data);
    }

    pub fn fileCount(self: *const MmapTrigramIndex) u32 {
        return @intCast(self.file_table.len);
    }

    pub fn containsFile(self: *const MmapTrigramIndex, path: []const u8) bool {
        return self.file_set.contains(path);
    }

    fn lookupTrigram(self: *const MmapTrigramIndex, tri_val: u32) ?struct { offset: u32, count: u32 } {
        const entries = self.lookup_entries;
        if (entries == 0) return null;
        var lo: usize = 0;
        var hi: usize = entries;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const entry_off = 12 + mid * @sizeOf(TrigramIndex.LookupEntry);
            const entry_tri = std.mem.readInt(u32, self.lookup_data[entry_off..][0..4], .little);
            if (entry_tri == tri_val) {
                const offset = std.mem.readInt(u32, self.lookup_data[entry_off + 4 ..][0..4], .little);
                const count = std.mem.readInt(u32, self.lookup_data[entry_off + 8 ..][0..4], .little);
                return .{ .offset = offset, .count = count };
            }
            if (entry_tri < tri_val) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return null;
    }

    fn lookupEntryAt(self: *const MmapTrigramIndex, idx: usize) TrigramIndex.LookupEntry {
        const entry_off = 12 + idx * @sizeOf(TrigramIndex.LookupEntry);
        return .{
            .trigram = std.mem.readInt(u32, self.lookup_data[entry_off..][0..4], .little),
            .offset = std.mem.readInt(u32, self.lookup_data[entry_off + 4 ..][0..4], .little),
            .count = std.mem.readInt(u32, self.lookup_data[entry_off + 8 ..][0..4], .little),
        };
    }

    fn readPosting(self: *const MmapTrigramIndex, index: usize) ?struct { file_id: u32, next_mask: u8, loc_mask: u8 } {
        const posting_size: usize = if (self.post_version >= 3) @sizeOf(TrigramIndex.DiskPosting) else @sizeOf(TrigramIndex.OldDiskPosting);
        const pb_off = self.postings_start + index * posting_size;
        if (pb_off + posting_size > self.postings_data.len) return null;
        const raw = self.postings_data[pb_off..][0..posting_size];
        const file_id: u32 = if (self.post_version >= 3)
            std.mem.readInt(u32, raw[0..4], .little)
        else
            std.mem.readInt(u16, raw[0..2], .little);
        const next_mask = raw[if (self.post_version >= 3) 4 else 2];
        const loc_mask = raw[if (self.post_version >= 3) 5 else 3];
        return .{ .file_id = file_id, .next_mask = next_mask, .loc_mask = loc_mask };
    }

    pub fn candidates(self: *const MmapTrigramIndex, query: []const u8, allocator: std.mem.Allocator) ?[]const []const u8 {
        if (query.len < 3) return null;

        const tri_count = query.len - 2;

        // Collect unique trigrams
        var unique = std.AutoHashMap(Trigram, void).init(allocator);
        defer unique.deinit();
        unique.ensureTotalCapacity(@intCast(tri_count)) catch return null;
        for (0..tri_count) |i| {
            const tri = packTrigram(
                normalizeChar(query[i]),
                normalizeChar(query[i + 1]),
                normalizeChar(query[i + 2]),
            );
            _ = unique.getOrPut(tri) catch return null;
        }

        // Collect posting ranges for each trigram, sorted by count (smallest first)
        const Range = struct { offset: u32, count: u32 };
        var ranges: std.ArrayList(Range) = .empty;
        defer ranges.deinit(allocator);
        ranges.ensureTotalCapacity(allocator, unique.count()) catch return null;

        var tri_iter = unique.keyIterator();
        while (tri_iter.next()) |tri_ptr| {
            const r = self.lookupTrigram(@as(u32, tri_ptr.*)) orelse {
                return allocator.alloc([]const u8, 0) catch null;
            };
            ranges.appendAssumeCapacity(.{ .offset = r.offset, .count = r.count });
        }

        if (ranges.items.len == 0) {
            return allocator.alloc([]const u8, 0) catch null;
        }

        std.mem.sort(Range, ranges.items, {}, struct {
            fn lt(_: void, a: Range, b: Range) bool {
                return a.count < b.count;
            }
        }.lt);

        // Seed with file_ids from smallest posting range
        var result_ids: std.ArrayList(u32) = .empty;
        defer result_ids.deinit(allocator);
        result_ids.ensureTotalCapacity(allocator, ranges.items[0].count) catch return null;
        for (0..ranges.items[0].count) |pi| {
            const p = self.readPosting(ranges.items[0].offset + pi) orelse continue;
            result_ids.appendAssumeCapacity(p.file_id);
        }

        // Intersect with subsequent ranges (sorted merge)
        for (ranges.items[1..]) |range| {
            var write: usize = 0;
            var si: usize = 0;
            for (result_ids.items) |id| {
                while (si < range.count) {
                    const p = self.readPosting(range.offset + si) orelse break;
                    if (p.file_id >= id) {
                        if (p.file_id == id) {
                            result_ids.items[write] = id;
                            write += 1;
                            si += 1;
                        }
                        break;
                    }
                    si += 1;
                }
            }
            result_ids.items.len = write;
            if (write == 0) break;
        }

        // Bloom filter verification for consecutive trigram pairs
        var result: std.ArrayList([]const u8) = .empty;
        errdefer result.deinit(allocator);
        result.ensureTotalCapacity(allocator, result_ids.items.len) catch return null;

        next_cand: for (result_ids.items) |file_id| {
            if (tri_count >= 2) {
                for (0..tri_count - 1) |j| {
                    const tri_a_val = @as(u32, packTrigram(
                        normalizeChar(query[j]),
                        normalizeChar(query[j + 1]),
                        normalizeChar(query[j + 2]),
                    ));
                    const tri_b_val = @as(u32, packTrigram(
                        normalizeChar(query[j + 1]),
                        normalizeChar(query[j + 2]),
                        normalizeChar(query[j + 3]),
                    ));
                    const range_a = self.lookupTrigram(tri_a_val) orelse continue;
                    const range_b = self.lookupTrigram(tri_b_val) orelse continue;
                    const mask_a = self.findPostingMask(range_a.offset, range_a.count, file_id) orelse continue;
                    const mask_b = self.findPostingMask(range_b.offset, range_b.count, file_id) orelse continue;

                    const next_bit: u8 = @as(u8, 1) << @intCast(normalizeChar(query[j + 3]) % 8);
                    if ((mask_a.next_mask & next_bit) == 0) continue :next_cand;

                    const rotated = (mask_a.loc_mask << 1) | (mask_a.loc_mask >> 7);
                    if ((rotated & mask_b.loc_mask) == 0) continue :next_cand;
                }
            }

            if (file_id < self.file_table.len) {
                result.appendAssumeCapacity(self.file_table[file_id]);
            }
        }

        return result.toOwnedSlice(allocator) catch {
            result.deinit(allocator);
            return null;
        };
    }

    fn findPostingMask(self: *const MmapTrigramIndex, offset: u32, count: u32, file_id: u32) ?PostingMask {
        var lo: usize = 0;
        var hi: usize = count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const p = self.readPosting(offset + mid) orelse return null;
            if (p.file_id == file_id) return PostingMask{ .next_mask = p.next_mask, .loc_mask = p.loc_mask };
            if (p.file_id < file_id) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return null;
    }

    pub fn candidatesRegex(self: *const MmapTrigramIndex, query: *const RegexQuery, allocator: std.mem.Allocator) ?[]const []const u8 {
        if (query.and_trigrams.len == 0 and query.or_groups.len == 0) return null;

        var result_set: ?std.AutoHashMap(u32, void) = null;
        defer if (result_set) |*rs| rs.deinit();

        if (query.and_trigrams.len > 0) {
            for (query.and_trigrams) |tri| {
                const range = self.lookupTrigram(@as(u32, tri)) orelse {
                    return allocator.alloc([]const u8, 0) catch null;
                };
                if (result_set == null) {
                    result_set = std.AutoHashMap(u32, void).init(allocator);
                    for (0..range.count) |pi| {
                        const p = self.readPosting(range.offset + pi) orelse continue;
                        result_set.?.put(p.file_id, {}) catch return null;
                    }
                } else {
                    var to_remove: std.ArrayList(u32) = .empty;
                    defer to_remove.deinit(allocator);
                    var it = result_set.?.keyIterator();
                    while (it.next()) |key| {
                        if (self.findPostingMask(range.offset, range.count, key.*) == null) {
                            to_remove.append(allocator, key.*) catch return null;
                        }
                    }
                    for (to_remove.items) |key| {
                        _ = result_set.?.remove(key);
                    }
                }
            }
        }

        for (query.or_groups) |group| {
            if (group.len == 0) continue;

            var union_set = std.AutoHashMap(u32, void).init(allocator);
            defer union_set.deinit();
            for (group) |tri| {
                const range = self.lookupTrigram(@as(u32, tri)) orelse continue;
                for (0..range.count) |pi| {
                    const p = self.readPosting(range.offset + pi) orelse continue;
                    union_set.put(p.file_id, {}) catch return null;
                }
            }

            if (result_set == null) {
                result_set = std.AutoHashMap(u32, void).init(allocator);
                var it = union_set.keyIterator();
                while (it.next()) |key| {
                    result_set.?.put(key.*, {}) catch return null;
                }
            } else {
                var to_remove: std.ArrayList(u32) = .empty;
                defer to_remove.deinit(allocator);
                var it = result_set.?.keyIterator();
                while (it.next()) |key| {
                    if (!union_set.contains(key.*)) {
                        to_remove.append(allocator, key.*) catch return null;
                    }
                }
                for (to_remove.items) |key| {
                    _ = result_set.?.remove(key);
                }
            }
        }

        if (result_set == null) return null;

        var result: std.ArrayList([]const u8) = .empty;
        errdefer result.deinit(allocator);
        result.ensureTotalCapacity(allocator, result_set.?.count()) catch return null;
        var it = result_set.?.keyIterator();
        while (it.next()) |id_ptr| {
            const doc_id = id_ptr.*;
            if (doc_id < self.file_table.len) {
                result.appendAssumeCapacity(self.file_table[doc_id]);
            }
        }
        return result.toOwnedSlice(allocator) catch {
            result.deinit(allocator);
            return null;
        };
    }
};

pub const AnyTrigramIndex = union(enum) {
    heap: TrigramIndex,
    mmap: MmapTrigramIndex,
    mmap_overlay: MmapOverlay,

    pub const MmapOverlay = struct {
        base: MmapTrigramIndex,
        overlay: TrigramIndex,
        /// Paths whose base entries are superseded (re-indexed into the
        /// overlay) or removed. Owns its keys; base answers for these paths
        /// are filtered out everywhere.
        masked: std.StringHashMap(void),
        masked_in_base: u32 = 0,

        pub fn mask(self: *MmapOverlay, path: []const u8) void {
            if (self.masked.contains(path)) return;
            const key = self.overlay.allocator.dupe(u8, path) catch return;
            self.masked.put(key, {}) catch {
                self.overlay.allocator.free(key);
                return;
            };
            if (self.base.containsFile(path)) self.masked_in_base += 1;
        }

        pub fn deinit(self: *MmapOverlay) void {
            var it = self.masked.keyIterator();
            while (it.next()) |k| self.overlay.allocator.free(k.*);
            self.masked.deinit();
            self.base.deinit();
            self.overlay.deinit();
        }
    };

    pub fn deinit(self: *AnyTrigramIndex) void {
        switch (self.*) {
            .heap => |*h| h.deinit(),
            .mmap => |*m| m.deinit(),
            .mmap_overlay => |*mo| mo.deinit(),
        }
    }

    pub fn candidates(self: *AnyTrigramIndex, query: []const u8, allocator: std.mem.Allocator) ?[]const []const u8 {
        return switch (self.*) {
            .heap => |*h| h.candidates(query, allocator),
            .mmap => |*m| m.candidates(query, allocator),
            .mmap_overlay => |*mo| blk: {
                const base = mo.base.candidates(query, allocator);
                const over = mo.overlay.candidates(query, allocator);
                break :blk mergeOverlayCandidates(mo, base, over, allocator);
            },
        };
    }

    /// Merge base + overlay candidate lists, dropping base hits for masked
    /// (superseded or removed) paths. Returns null on alloc failure so callers
    /// fall back to the full scan.
    fn mergeOverlayCandidates(
        mo: *const MmapOverlay,
        base: ?[]const []const u8,
        over: ?[]const []const u8,
        allocator: std.mem.Allocator,
    ) ?[]const []const u8 {
        if (base == null and over == null) return null;
        if (base == null) return over;
        var merged = std.StringHashMap(void).init(allocator);
        defer merged.deinit();
        var failed = false;
        for (base.?) |p| {
            if (mo.masked.contains(p)) continue;
            merged.put(p, {}) catch {
                failed = true;
                break;
            };
        }
        if (!failed) if (over) |ov| {
            for (ov) |p| {
                merged.put(p, {}) catch {
                    failed = true;
                    break;
                };
            }
        };
        allocator.free(base.?);
        if (over) |ov| allocator.free(ov);
        if (failed) return null;
        var result: std.ArrayList([]const u8) = .empty;
        result.ensureTotalCapacity(allocator, merged.count()) catch return null;
        var it = merged.keyIterator();
        while (it.next()) |k| result.appendAssumeCapacity(k.*);
        return result.toOwnedSlice(allocator) catch {
            result.deinit(allocator);
            return null;
        };
    }

    pub fn candidatesRegex(self: *AnyTrigramIndex, query: *const RegexQuery, allocator: std.mem.Allocator) ?[]const []const u8 {
        return switch (self.*) {
            .heap => |*h| h.candidatesRegex(query, allocator),
            .mmap => |*m| m.candidatesRegex(query, allocator),
            .mmap_overlay => |*mo| blk: {
                const base = mo.base.candidatesRegex(query, allocator);
                const over = mo.overlay.candidatesRegex(query, allocator);
                break :blk mergeOverlayCandidates(mo, base, over, allocator);
            },
        };
    }

    pub fn containsFile(self: *const AnyTrigramIndex, path: []const u8) bool {
        return switch (self.*) {
            .heap => |*h| h.file_trigrams.contains(path),
            .mmap => |*m| m.containsFile(path),
            .mmap_overlay => |*mo| (mo.base.containsFile(path) and !mo.masked.contains(path)) or
                mo.overlay.file_trigrams.contains(path),
        };
    }

    pub fn indexFile(self: *AnyTrigramIndex, path: []const u8, content: []const u8) !void {
        switch (self.*) {
            .heap => |*h| try h.indexFile(path, content),
            .mmap => |*m| {
                // Promote to mmap_overlay: keep mmap base, add heap overlay
                const alloc = m.allocator;
                const base = self.mmap;
                self.* = .{ .mmap_overlay = .{
                    .base = base,
                    .overlay = TrigramIndex.init(alloc),
                    .masked = std.StringHashMap(void).init(alloc),
                } };
                try self.mmap_overlay.overlay.indexFile(path, content);
                self.mmap_overlay.mask(path);
            },
            .mmap_overlay => |*mo| {
                try mo.overlay.indexFile(path, content);
                mo.mask(path);
            },
        }
    }

    pub fn removeFile(self: *AnyTrigramIndex, path: []const u8) void {
        switch (self.*) {
            .heap => |*h| h.removeFile(path),
            .mmap => |*m| {
                // A remove is a write: promote so the base entry can be masked.
                if (!m.containsFile(path)) return;
                const alloc = m.allocator;
                const base = self.mmap;
                self.* = .{ .mmap_overlay = .{
                    .base = base,
                    .overlay = TrigramIndex.init(alloc),
                    .masked = std.StringHashMap(void).init(alloc),
                } };
                self.mmap_overlay.mask(path);
            },
            .mmap_overlay => |*mo| {
                mo.overlay.removeFile(path);
                mo.mask(path);
            },
        }
    }

    pub fn writeToDisk(self: *AnyTrigramIndex, io: std.Io, dir_path: []const u8, git_head: ?[40]u8) !void {
        switch (self.*) {
            .heap => |*h| try h.writeToDisk(io, dir_path, git_head),
            // A pure mmap view holds no in-memory changes — the disk files
            // already are the index.
            .mmap => {},
            .mmap_overlay => |*mo| {
                var merged = try materializeOverlay(mo);
                defer merged.deinit();
                try merged.writeToDisk(io, dir_path, git_head);
            },
        }
    }

    /// Rebuild the merged logical state (base minus masked paths, plus
    /// overlay) as a heap TrigramIndex so the heap serializer can persist
    /// it. That serializer is tmp+rename atomic, so writing over the very
    /// directory the live base is mmapped from is safe — the mapping keeps
    /// the old inode alive.
    fn materializeOverlay(mo: *const MmapOverlay) !TrigramIndex {
        const alloc = mo.overlay.allocator;
        var merged = TrigramIndex.init(alloc);
        merged.owns_paths = true;
        errdefer merged.deinit();

        for (mo.base.file_table) |path| {
            if (mo.masked.contains(path)) continue;
            try mergedAddFile(&merged, path);
        }
        var overlay_files = mo.overlay.file_trigrams.keyIterator();
        while (overlay_files.next()) |path_ptr| {
            try mergedAddFile(&merged, path_ptr.*);
        }

        for (0..mo.base.lookup_entries) |e| {
            const entry = mo.base.lookupEntryAt(e);
            const tri: Trigram = @intCast(entry.trigram);
            for (0..entry.count) |pi| {
                const p = mo.base.readPosting(entry.offset + pi) orelse continue;
                if (p.file_id >= mo.base.file_table.len) continue;
                const path = mo.base.file_table[p.file_id];
                if (mo.masked.contains(path)) continue;
                try mergedInsert(&merged, tri, path, p.next_mask, p.loc_mask);
            }
        }

        var overlay_tris = mo.overlay.index.iterator();
        while (overlay_tris.next()) |te| {
            for (te.value_ptr.items.items) |p| {
                if (p.doc_id >= mo.overlay.id_to_path.items.len) continue;
                const path = mo.overlay.id_to_path.items[p.doc_id];
                if (path.len == 0) continue;
                try mergedInsert(&merged, te.key_ptr.*, path, p.next_mask, p.loc_mask);
            }
        }
        return merged;
    }

    fn mergedAddFile(merged: *TrigramIndex, path: []const u8) !void {
        const doc_id = try merged.getOrCreateDocId(path);
        const stable = merged.id_to_path.items[doc_id];
        if (!merged.file_trigrams.contains(stable)) {
            try merged.file_trigrams.put(stable, .empty);
        }
    }

    fn mergedInsert(merged: *TrigramIndex, tri: Trigram, path: []const u8, next_mask: u8, loc_mask: u8) !void {
        const doc_id = merged.path_to_id.get(path) orelse return;
        const gop = try merged.index.getOrPut(tri);
        if (!gop.found_existing) {
            gop.value_ptr.* = .{ .path_to_id = &merged.path_to_id };
        }
        const posting = try gop.value_ptr.getOrAddPosting(merged.allocator, doc_id);
        posting.next_mask |= next_mask;
        posting.loc_mask |= loc_mask;
        const stable = merged.id_to_path.items[doc_id];
        const tri_list = merged.file_trigrams.getPtr(stable) orelse return;
        if (tri_list.items.len == 0 or tri_list.items[tri_list.items.len - 1] != tri) {
            try tri_list.append(merged.allocator, tri);
        }
    }

    pub fn fileCount(self: *const AnyTrigramIndex) u32 {
        return switch (self.*) {
            .heap => |*h| h.fileCount(),
            .mmap => |*m| m.fileCount(),
            .mmap_overlay => |*mo| mo.base.fileCount() + mo.overlay.fileCount() - mo.masked_in_base,
        };
    }

    pub fn asHeap(self: *AnyTrigramIndex) ?*TrigramIndex {
        return switch (self.*) {
            .heap => |*h| h,
            .mmap => null,
            .mmap_overlay => |*mo| &mo.overlay,
        };
    }
};
// ── Regex decomposition ─────────────────────────────────────

pub const RegexQuery = struct {
    and_trigrams: []Trigram,
    or_groups: [][]Trigram,
    allocator: std.mem.Allocator,

    pub fn deinit(self: *RegexQuery) void {
        self.allocator.free(self.and_trigrams);
        for (self.or_groups) |group| {
            self.allocator.free(group);
        }
        self.allocator.free(self.or_groups);
    }
};

/// Parse a regex pattern and extract literal segments that yield trigrams.
/// Handles: . \s \w \d * + ? | [...] \ (escapes)
/// Literal runs >= 3 chars produce AND trigrams.
/// Alternations (foo|bar) produce OR groups.
pub fn decomposeRegex(pattern: []const u8, allocator: std.mem.Allocator) !RegexQuery {
    // First check if this is an alternation at the top level
    // We need to respect grouping: only split on | outside of [...] and (...)
    var top_pipes: std.ArrayList(usize) = .empty;
    defer top_pipes.deinit(allocator);

    {
        var depth: usize = 0;
        var in_bracket = false;
        var i: usize = 0;
        while (i < pattern.len) {
            const c = pattern[i];
            if (c == '\\' and i + 1 < pattern.len) {
                i += 2;
                continue;
            }
            if (c == '[') {
                in_bracket = true;
                i += 1;
                continue;
            }
            if (c == ']') {
                in_bracket = false;
                i += 1;
                continue;
            }
            if (in_bracket) {
                i += 1;
                continue;
            }
            if (c == '(') {
                depth += 1;
                i += 1;
                continue;
            }
            if (c == ')') {
                if (depth > 0) depth -= 1;
                i += 1;
                continue;
            }
            if (c == '|' and depth == 0) {
                try top_pipes.append(allocator, i);
            }
            i += 1;
        }
    }

    if (top_pipes.items.len > 0) {
        // Top-level alternation: merge all branch trigrams into a single OR group.
        // A file matching ANY branch's trigrams is a valid candidate.
        //
        // Soundness (#628): if ANY branch yields no trigrams (too short, or built
        // from regex metachars like `.`/`.*`), that branch can match a line that
        // contains none of the other branches' trigrams. Constraining candidates
        // to only the trigram-bearing branches would then silently drop real
        // matches — exactly the `a|b` "returns 0 and looks authoritative" bug.
        // When that happens we cannot prefilter at all, so fall back to an
        // unconstrained query (candidatesRegex returns null -> scan everything).
        var all_tris: std.ArrayList(Trigram) = .empty;
        errdefer all_tris.deinit(allocator);

        var any_branch_empty = false;
        var start: usize = 0;
        for (top_pipes.items) |pipe_pos| {
            const branch = pattern[start..pipe_pos];
            const branch_tris = try extractLiteralTrigrams(branch, allocator);
            defer allocator.free(branch_tris);
            if (branch_tris.len == 0) any_branch_empty = true;
            for (branch_tris) |tri| {
                try all_tris.append(allocator, tri);
            }
            start = pipe_pos + 1;
        }
        // Last branch
        const last_branch = pattern[start..];
        const last_tris = try extractLiteralTrigrams(last_branch, allocator);
        defer allocator.free(last_tris);
        if (last_tris.len == 0) any_branch_empty = true;
        for (last_tris) |tri| {
            try all_tris.append(allocator, tri);
        }

        if (any_branch_empty) {
            // Un-prefilterable alternation: scan everything rather than miss matches.
            all_tris.deinit(allocator);
            all_tris = .empty;
            const e_and = try allocator.alloc(Trigram, 0);
            const e_or = try allocator.alloc([]Trigram, 0);
            return RegexQuery{
                .and_trigrams = e_and,
                .or_groups = e_or,
                .allocator = allocator,
            };
        }

        const empty_and = try allocator.alloc(Trigram, 0);
        var or_groups: std.ArrayList([]Trigram) = .empty;
        errdefer or_groups.deinit(allocator);
        if (all_tris.items.len > 0) {
            try or_groups.append(allocator, try all_tris.toOwnedSlice(allocator));
        }
        return RegexQuery{
            .and_trigrams = empty_and,
            .or_groups = try or_groups.toOwnedSlice(allocator),
            .allocator = allocator,
        };
    }

    // No top-level alternation: extract trigrams from literal segments
    const and_tris = try extractLiteralTrigrams(pattern, allocator);
    const empty_or = try allocator.alloc([]Trigram, 0);
    return RegexQuery{
        .and_trigrams = and_tris,
        .or_groups = empty_or,
        .allocator = allocator,
    };
}

/// Extract trigrams from literal runs in a regex fragment (no top-level |).
fn extractLiteralTrigrams(pattern: []const u8, allocator: std.mem.Allocator) ![]Trigram {
    var literals: std.ArrayList(u8) = .empty;
    defer literals.deinit(allocator);

    var trigrams_list: std.ArrayList(Trigram) = .empty;
    errdefer trigrams_list.deinit(allocator);

    // Deduplicate trigrams
    var seen = std.AutoHashMap(Trigram, void).init(allocator);
    defer seen.deinit();

    var i: usize = 0;
    while (i < pattern.len) {
        const c = pattern[i];

        // Escape sequences
        if (c == '\\' and i + 1 < pattern.len) {
            const next = pattern[i + 1];
            switch (next) {
                's', 'S', 'w', 'W', 'd', 'D', 'b', 'B' => {
                    // Character class — breaks literal chain
                    try flushLiterals(allocator, &literals, &trigrams_list, &seen);
                    i += 2;
                    // If followed by quantifier, skip it too
                    if (i < pattern.len and isQuantifier(pattern[i])) i += 1;
                    continue;
                },
                else => {
                    // Escaped literal char (e.g. \. \( \) \\ etc.)
                    try literals.append(allocator, next);
                    i += 2;
                    // Check for quantifier after escaped char
                    if (i < pattern.len and isQuantifier(pattern[i])) {
                        // Quantifier on single char — pop it and flush
                        if (literals.items.len > 0) {
                            _ = literals.pop();
                        }
                        try flushLiterals(allocator, &literals, &trigrams_list, &seen);
                        i += 1;
                    }
                    continue;
                },
            }
        }

        // Character class [...]
        if (c == '[') {
            try flushLiterals(allocator, &literals, &trigrams_list, &seen);
            // Skip to closing ]
            i += 1;
            if (i < pattern.len and pattern[i] == '^') i += 1;
            if (i < pattern.len and pattern[i] == ']') i += 1; // literal ] at start
            while (i < pattern.len and pattern[i] != ']') : (i += 1) {}
            if (i < pattern.len) i += 1; // skip ]
            // Skip quantifier after class
            if (i < pattern.len and isQuantifier(pattern[i])) i += 1;
            continue;
        }

        // Grouping parens — just skip them, process contents
        if (c == '(' or c == ')') {
            try flushLiterals(allocator, &literals, &trigrams_list, &seen);
            i += 1;
            continue;
        }

        // Anchors
        if (c == '^' or c == '$') {
            try flushLiterals(allocator, &literals, &trigrams_list, &seen);
            i += 1;
            continue;
        }

        // Dot — any char, breaks chain
        if (c == '.') {
            try flushLiterals(allocator, &literals, &trigrams_list, &seen);
            i += 1;
            if (i < pattern.len and isQuantifier(pattern[i])) i += 1;
            continue;
        }

        // Quantifiers on previous char
        if (isQuantifier(c)) {
            // Remove last literal (it's now optional/repeated)
            if (literals.items.len > 0) {
                _ = literals.pop();
            }
            try flushLiterals(allocator, &literals, &trigrams_list, &seen);
            // If it's a brace quantifier {n}, {n,m}, {n,}, skip to closing }
            if (c == '{') {
                i += 1;
                while (i < pattern.len and pattern[i] != '}') : (i += 1) {}
                if (i < pattern.len) i += 1; // skip '}'
            } else {
                i += 1;
            }
            continue;
        }

        // Plain literal character
        try literals.append(allocator, c);
        i += 1;
    }

    // Flush remaining literals
    try flushLiterals(allocator, &literals, &trigrams_list, &seen);

    return trigrams_list.toOwnedSlice(allocator);
}

fn isQuantifier(c: u8) bool {
    return c == '*' or c == '+' or c == '?' or c == '{';
}

/// Flush a run of literal characters into trigrams (if >= 3 chars).
fn flushLiterals(
    allocator: std.mem.Allocator,
    literals: *std.ArrayList(u8),
    trigrams_list: *std.ArrayList(Trigram),
    seen: *std.AutoHashMap(Trigram, void),
) !void {
    if (literals.items.len >= 3) {
        for (0..literals.items.len - 2) |j| {
            const tri = packTrigram(
                normalizeChar(literals.items[j]),
                normalizeChar(literals.items[j + 1]),
                normalizeChar(literals.items[j + 2]),
            );
            const gop = try seen.getOrPut(tri);
            if (!gop.found_existing) {
                try trigrams_list.append(allocator, tri);
            }
        }
    }
    literals.clearRetainingCapacity();
}

// ── Tokenizer ───────────────────────────────────────────────

pub const WordTokenizer = struct {
    buf: []const u8,
    pos: usize = 0,

    pub fn next(self: *WordTokenizer) ?[]const u8 {
        // Skip non-word chars
        while (self.pos < self.buf.len and !isWordChar(self.buf[self.pos])) {
            self.pos += 1;
        }
        if (self.pos >= self.buf.len) return null;

        const start = self.pos;
        while (self.pos < self.buf.len and isWordChar(self.buf[self.pos])) {
            self.pos += 1;
        }
        return self.buf[start..self.pos];
    }
};

fn isWordChar(c: u8) bool {
    return std.ascii.isAlphanumeric(c) or c == '_';
}

pub fn normalizeChar(c: u8) u8 {
    // Lowercase for case-insensitive trigram matching
    return if (c >= 'A' and c <= 'Z') c + 32 else c;
}

fn emitSubToken(seg: []const u8, out: *std.ArrayList([]const u8), arena: std.mem.Allocator) !void {
    if (seg.len < 2) return;
    const lower = try arena.alloc(u8, seg.len);
    for (seg, 0..) |c, j| lower[j] = normalizeChar(c);
    try out.append(arena, lower);
}

/// Split an identifier into lowercased sub-tokens.
/// Handles: snake_case, camelCase, SCREAMING_CASE, HTTPHandler-style acronyms.
/// Appends to `out`; strings are allocated from `arena`.
pub fn splitIdentifier(token: []const u8, out: *std.ArrayList([]const u8), arena: std.mem.Allocator) !void {
    if (token.len < 2) return;

    var start: usize = 0;
    var i: usize = 1;
    while (i < token.len) : (i += 1) {
        const c = token[i];
        const prev = token[i - 1];
        var split = false;

        if (c == '_') {
            try emitSubToken(token[start..i], out, arena);
            start = i + 1;
            continue;
        }
        if (prev == '_') continue;

        // CamelCase: lowercase → uppercase boundary
        if (c >= 'A' and c <= 'Z' and prev >= 'a' and prev <= 'z') split = true;

        // Digit/letter transition
        if (!split) {
            const c_d = c >= '0' and c <= '9';
            const p_d = prev >= '0' and prev <= '9';
            if (c_d != p_d) split = true;
        }

        // Acronym end: HTTPHandler → HTTP|Handler
        if (!split and c >= 'A' and c <= 'Z' and prev >= 'A' and prev <= 'Z') {
            if (i + 1 < token.len and token[i + 1] >= 'a' and token[i + 1] <= 'z') split = true;
        }

        if (split) {
            try emitSubToken(token[start..i], out, arena);
            start = i;
        }
    }
    try emitSubToken(token[start..token.len], out, arena);
}
// ── Sparse N-gram index ───────────────────────────────────────────────────────

pub const MAX_NGRAM_LEN: usize = 16;

/// Comptime character-pair frequency table for source code.
/// Common pairs → LOW weight (they stay interior to n-grams).
/// Rare pairs   → HIGH weight (they become n-gram boundaries).
/// All unspecified pairs default to 0xFE00 (rare = high weight).
pub const default_pair_freq: [256][256]u16 = blk: {
    var table: [256][256]u16 = .{.{0xFE00} ** 256} ** 256;
    // English bigrams (lowercase) — common in identifiers and prose
    table['t']['h'] = 0x1000;
    table['h']['e'] = 0x1000;
    table['i']['n'] = 0x1000;
    table['e']['r'] = 0x1000;
    table['a']['n'] = 0x1000;
    table['r']['e'] = 0x1000;
    table['o']['n'] = 0x1000;
    table['e']['n'] = 0x1000;
    table['s']['t'] = 0x1000;
    table['e']['s'] = 0x1000;
    table['a']['t'] = 0x1000;
    table['i']['o'] = 0x1000;
    table['t']['e'] = 0x1000;
    table['o']['r'] = 0x1000;
    table['t']['i'] = 0x1000;
    table['a']['r'] = 0x1000;
    table['a']['l'] = 0x1000;
    table['l']['e'] = 0x1000;
    table['n']['t'] = 0x1000;
    table['e']['d'] = 0x1000;
    table['n']['d'] = 0x1000;
    table['o']['u'] = 0x1000;
    table['e']['a'] = 0x1000;
    table['f']['o'] = 0x1000;
    // Common code keyword fragments
    table['f']['n'] = 0x1000;
    table['i']['f'] = 0x1000;
    table['r']['n'] = 0x1000;
    table['t']['u'] = 0x1000;
    table['p']['u'] = 0x1000;
    table['b']['l'] = 0x1000;
    table['c']['o'] = 0x1000;
    table['n']['s'] = 0x1000;
    table['t']['r'] = 0x1000;
    table['u']['e'] = 0x1000;
    // Common operator / punctuation pairs
    table['('][')'] = 0x0800;
    table['{']['}'] = 0x0800;
    table['['][']'] = 0x0800;
    table['/']['/'] = 0x0800;
    table['-']['>'] = 0x0800;
    table['=']['>'] = 0x0800;
    table[':'][':'] = 0x0800;
    table['!']['='] = 0x0800;
    table['=']['='] = 0x0800;
    table['<']['='] = 0x0800;
    table['>']['='] = 0x0800;
    table['&']['&'] = 0x0800;
    table['|']['|'] = 0x0800;
    // Whitespace / structural pairs
    table[' '][' '] = 0x0800;
    table['\t'][' '] = 0x0800;
    table[' ']['('] = 0x0800;
    table[' ']['{'] = 0x0800;
    table[';'][' '] = 0x0800;
    table[':'][' '] = 0x0800;
    table['='][' '] = 0x0800;
    table[' ']['='] = 0x0800;
    table[','][' '] = 0x0800;
    table['.']['.'] = 0x0800;
    table['\n'][' '] = 0x0800;
    table['\n']['\t'] = 0x0800;
    break :blk table;
};

/// Active frequency table — points to the comptime default or a runtime
/// per-project table.  Swap only before indexing starts (not thread-safe).
pub var active_pair_freq: *const [256][256]u16 = &default_pair_freq;
var loaded_freq_table: [256][256]u16 = undefined;

/// Deterministic weight for a character pair, used to place content-defined
/// boundaries between n-grams.  Frequency-weighted: common source-code pairs
/// get LOW weight (they stay interior to n-grams); rare pairs get HIGH weight
/// (they become boundaries).  A small hash jitter (0-255) breaks ties
/// deterministically between pairs in the same frequency tier.
pub fn pairWeight(a: u8, b: u8) u16 {
    const freq_weight = active_pair_freq[a][b];
    const pair = [2]u8{ a, b };
    const jitter: u16 = @truncate(std.hash.Wyhash.hash(0, &pair) & 0xFF);
    return freq_weight +| jitter;
}

/// Swap in a custom frequency table.  Call before indexing; not thread-safe.
pub fn setFrequencyTable(table: *const [256][256]u16) void {
    loaded_freq_table = table.*;
    active_pair_freq = &loaded_freq_table;
}

/// Revert to the built-in comptime frequency table.
pub fn resetFrequencyTable() void {
    active_pair_freq = &default_pair_freq;
}

/// Build a per-project frequency table by counting byte-pair occurrences in
/// `content`, then inverting counts to weights (common → low, rare → high).
pub fn buildFrequencyTable(content: []const u8) [256][256]u16 {
    var counts: [256][256]u64 = .{.{0} ** 256} ** 256;
    if (content.len >= 2) {
        for (0..content.len - 1) |i| {
            counts[content[i]][content[i + 1]] += 1;
        }
    }
    return finishFrequencyTable(&counts);
}

/// Build a frequency table by streaming over multiple content slices.
/// Zero extra memory — counts pairs within each slice, skipping cross-slice
/// boundaries (negligible loss for large corpora).
pub fn buildFrequencyTableFromSlices(slices: []const []const u8) [256][256]u16 {
    var counts: [256][256]u64 = .{.{0} ** 256} ** 256;
    for (slices) |content| {
        if (content.len < 2) continue;
        for (0..content.len - 1) |i| {
            counts[content[i]][content[i + 1]] += 1;
        }
    }
    return finishFrequencyTable(&counts);
}

/// Build a frequency table by streaming over a StringHashMap of content.
/// Iterates file-by-file — no concatenation, zero extra memory.
pub fn buildFrequencyTableFromMap(contents: *ContentCache) [256][256]u16 {
    var counts: [256][256]u64 = .{.{0} ** 256} ** 256;
    var iter = contents.iterator();
    while (iter.next()) |entry| {
        const content = entry.value_ptr.*;
        if (content.len < 2) continue;
        for (0..content.len - 1) |i| {
            counts[content[i]][content[i + 1]] += 1;
        }
    }
    return finishFrequencyTable(&counts);
}

fn finishFrequencyTable(counts: *const [256][256]u64) [256][256]u16 {
    var max_count: u64 = 1;
    for (counts) |row| {
        for (row) |c| {
            if (c > max_count) max_count = c;
        }
    }
    // Invert: count 0 → 0xFE00 (rare, high); max_count → 0x1000 (common, low).
    var table: [256][256]u16 = .{.{0xFE00} ** 256} ** 256;
    for (0..256) |a| {
        for (0..256) |b| {
            const c = counts[a][b];
            if (c == 0) continue;
            const span: u64 = 0xFE00 - 0x1000;
            const w: u64 = 0xFE00 - (c * span / max_count);
            table[a][b] = @intCast(@min(w, 0xFE00));
        }
    }
    return table;
}

/// Persist a frequency table as a raw binary blob to `<dir_path>/pair_freq.bin`.
/// Uses tmp+rename for atomic writes.
pub fn writeFrequencyTable(io: std.Io, table: *const [256][256]u16, dir_path: []const u8) !void {
    var dir = try std.Io.Dir.cwd().openDir(io, dir_path, .{});
    defer dir.close(io);
    {
        const tmp = try dir.createFile(io, "pair_freq.bin.tmp", .{});
        defer tmp.close(io);
        var tw_buf: [64 * 1024]u8 = undefined;
        var tw = tmp.writer(io, &tw_buf);
        var row_buf: [256 * 2]u8 = undefined;
        for (table) |row| {
            for (row, 0..) |val, j| {
                std.mem.writeInt(u16, row_buf[j * 2 ..][0..2], val, .little);
            }
            try tw.interface.writeAll(&row_buf);
        }
        try tw.interface.flush();
    }
    try dir.rename("pair_freq.bin.tmp", dir, "pair_freq.bin", io);
}

/// Load a frequency table from `<dir_path>/pair_freq.bin`.
/// Returns null if the file does not exist or has the wrong size.
/// Caller owns the returned allocation.
pub fn readFrequencyTable(io: std.Io, dir_path: []const u8, allocator: std.mem.Allocator) !?*[256][256]u16 {
    const path = try std.fmt.allocPrint(allocator, "{s}/pair_freq.bin", .{dir_path});
    defer allocator.free(path);
    const file = std.Io.Dir.cwd().openFile(io, path, .{}) catch |err| switch (err) {
        error.FileNotFound => return null,
        else => return err,
    };
    defer file.close(io);
    const expected_size = 256 * 256 * @sizeOf(u16);
    const size = try file.length(io);
    if (size != expected_size) return null;
    const result = try allocator.create([256][256]u16);
    errdefer allocator.destroy(result);
    var read_pos: u64 = 0;
    var row_buf: [256 * 2]u8 = undefined;
    for (result) |*row| {
        const n = try file.readPositionalAll(io, &row_buf, read_pos);
        if (n != row_buf.len) {
            allocator.destroy(result);
            return null;
        }
        read_pos += row_buf.len;
        for (row, 0..) |*val, j| {
            val.* = std.mem.readInt(u16, row_buf[j * 2 ..][0..2], .little);
        }
    }
    return result;
}

/// A single sparse n-gram extracted from a string.
pub const SparseNgram = struct {
    hash: u64, // Wyhash of the normalized (lowercased) n-gram bytes
    pos: usize, // byte offset in the source string
    len: usize, // byte length of the n-gram
};

fn makeNgram(content: []const u8, pos: usize, len: usize) SparseNgram {
    var buf: [MAX_NGRAM_LEN]u8 = undefined;
    for (0..len) |k| buf[k] = normalizeChar(content[pos + k]);
    return .{
        .hash = std.hash.Wyhash.hash(0, buf[0..len]),
        .pos = pos,
        .len = len,
    };
}

/// Extract sparse n-grams from `content` using content-defined boundaries.
///
/// Boundaries are placed at strict local maxima of pairWeight over the
/// normalized character pairs.  N-grams span consecutive boundaries; spans
/// wider than MAX_NGRAM_LEN are force-split into MAX_NGRAM_LEN chunks.
/// Minimum n-gram length is 3 (same as a trigram).
///
/// Caller owns the returned slice.
pub fn extractSparseNgrams(content: []const u8, allocator: std.mem.Allocator) ![]SparseNgram {
    const MIN_LEN = 3;
    if (content.len < MIN_LEN) return try allocator.alloc(SparseNgram, 0);

    const pair_count = content.len - 1;

    // Compute pair weights.
    const weights = try allocator.alloc(u16, pair_count);
    defer allocator.free(weights);
    for (0..pair_count) |i| {
        weights[i] = pairWeight(normalizeChar(content[i]), normalizeChar(content[i + 1]));
    }

    // Collect boundary pair-positions: always include 0 and pair_count-1,
    // plus any interior strict local maximum.
    var bounds: std.ArrayList(usize) = .empty;
    defer bounds.deinit(allocator);

    try bounds.append(allocator, 0);
    if (pair_count >= 3) {
        for (1..pair_count - 1) |i| {
            if (weights[i] > weights[i - 1] and weights[i] > weights[i + 1]) {
                try bounds.append(allocator, i);
            }
        }
    }
    try bounds.append(allocator, pair_count - 1);

    // Emit n-grams spanning consecutive boundary positions.
    // N-gram for boundary pair at position p covers content[p .. p+2].
    var result: std.ArrayList(SparseNgram) = .empty;
    errdefer result.deinit(allocator);

    var b: usize = 0;
    while (b + 1 < bounds.items.len) : (b += 1) {
        const start = bounds.items[b];
        const end_pair = bounds.items[b + 1];
        // The right-hand boundary pair covers content[end_pair .. end_pair+2].
        const ngram_end = end_pair + 2;
        const ngram_len = ngram_end - start;

        if (ngram_len < MIN_LEN) continue;

        if (ngram_len <= MAX_NGRAM_LEN) {
            try result.append(allocator, makeNgram(content, start, ngram_len));
        } else {
            // Force-split into MAX_NGRAM_LEN-sized chunks.
            var off = start;
            while (off + MAX_NGRAM_LEN <= ngram_end) {
                try result.append(allocator, makeNgram(content, off, MAX_NGRAM_LEN));
                off += MAX_NGRAM_LEN;
            }
            const rem = ngram_end - off;
            if (rem >= MIN_LEN) {
                try result.append(allocator, makeNgram(content, off, rem));
            } else if (rem > 0) {
                // Tail is too short for its own ngram.  Overlap with the
                // previous chunk by backing up to ngram_end - MIN_LEN so
                // every byte in the span is covered.
                try result.append(allocator, makeNgram(content, ngram_end - MIN_LEN, MIN_LEN));
            }
        }
    }

    return result.toOwnedSlice(allocator);
}

/// Build the covering set of n-gram hashes for a query using a sliding window.
/// Extracts every substring of the query with length in [3, MAX_NGRAM_LEN] so
/// that file boundary-based n-grams overlapping the query are matched regardless
/// of where content-defined boundaries fall in the indexed file.
/// Caller owns the returned slice.
pub fn buildCoveringSet(query: []const u8, allocator: std.mem.Allocator) ![]SparseNgram {
    const MIN_LEN = 3;
    if (query.len < MIN_LEN) return try allocator.alloc(SparseNgram, 0);

    var result: std.ArrayList(SparseNgram) = .empty;
    errdefer result.deinit(allocator);

    // Slide a window of every length [MIN_LEN, MAX_NGRAM_LEN] across the query.
    // This avoids boundary-misalignment false negatives when a query substring
    // appears in the indexed file as a content-defined boundary n-gram.
    var len: usize = MIN_LEN;
    while (len <= @min(MAX_NGRAM_LEN, query.len)) : (len += 1) {
        var pos: usize = 0;
        while (pos + len <= query.len) : (pos += 1) {
            try result.append(allocator, makeNgram(query, pos, len));
        }
    }

    return result.toOwnedSlice(allocator);
}

/// In-memory sparse n-gram index.  Mirrors the TrigramIndex API so it can
/// be used as a drop-in acceleration layer alongside the trigram index.
pub const SparseNgramIndex = struct {
    /// ngram hash → set of file paths that contain the n-gram
    index: std.AutoHashMap(u64, std.StringHashMap(void)),
    /// path → list of ngram hashes contributed (for cleanup on re-index)
    file_ngrams: std.StringHashMap(std.ArrayList(u64)),
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) SparseNgramIndex {
        return .{
            .index = std.AutoHashMap(u64, std.StringHashMap(void)).init(allocator),
            .file_ngrams = std.StringHashMap(std.ArrayList(u64)).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SparseNgramIndex) void {
        var iter = self.index.iterator();
        while (iter.next()) |entry| {
            entry.value_ptr.deinit();
        }
        self.index.deinit();

        var fn_iter = self.file_ngrams.iterator();
        while (fn_iter.next()) |entry| {
            entry.value_ptr.deinit(self.allocator);
        }
        self.file_ngrams.deinit();
    }

    pub fn removeFile(self: *SparseNgramIndex, path: []const u8) void {
        const ngrams = self.file_ngrams.getPtr(path) orelse return;
        for (ngrams.items) |hash| {
            if (self.index.getPtr(hash)) |file_set| {
                _ = file_set.remove(path);
                if (file_set.count() == 0) {
                    file_set.deinit();
                    _ = self.index.remove(hash);
                }
            }
        }
        ngrams.deinit(self.allocator);
        _ = self.file_ngrams.remove(path);
    }

    pub fn indexFile(self: *SparseNgramIndex, path: []const u8, content: []const u8) !void {
        self.removeFile(path);

        const ngrams = try extractSparseNgrams(content, self.allocator);
        defer self.allocator.free(ngrams);

        // Deduplicate hashes so the cleanup list stays compact.
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();

        for (ngrams) |ng| {
            const gop = try self.index.getOrPut(ng.hash);
            if (!gop.found_existing) {
                gop.value_ptr.* = std.StringHashMap(void).init(self.allocator);
            }
            _ = try gop.value_ptr.getOrPut(path);
            _ = try seen.getOrPut(ng.hash);
        }

        var hash_list: std.ArrayList(u64) = .empty;
        errdefer hash_list.deinit(self.allocator);
        var seen_iter = seen.keyIterator();
        while (seen_iter.next()) |h| {
            try hash_list.append(self.allocator, h.*);
        }
        try self.file_ngrams.put(path, hash_list);
    }

    /// Find candidate files that may contain the query string.
    /// Uses the sliding-window covering set from buildCoveringSet and returns
    /// the UNION of all matching posting lists — a superset of true matches,
    /// to be verified by content search.  Returns null when the query is too
    /// short.  Caller must free the returned slice.
    pub fn candidates(self: *SparseNgramIndex, query: []const u8, allocator: std.mem.Allocator) ?[]const []const u8 {
        const ngrams = buildCoveringSet(query, allocator) catch return null;
        defer allocator.free(ngrams);

        if (ngrams.len == 0) return null;

        // Union posting sets for all sliding-window n-gram hashes.
        // A file is a candidate if it shares any substring with the query.
        var seen_files = std.StringHashMap(void).init(allocator);
        defer seen_files.deinit();

        for (ngrams) |ng| {
            const file_set = self.index.getPtr(ng.hash) orelse continue;
            var it = file_set.keyIterator();
            while (it.next()) |path_ptr| {
                seen_files.put(path_ptr.*, {}) catch return null;
            }
        }

        if (seen_files.count() == 0) {
            return allocator.alloc([]const u8, 0) catch null;
        }

        var result: std.ArrayList([]const u8) = .empty;
        errdefer result.deinit(allocator);
        result.ensureTotalCapacity(allocator, seen_files.count()) catch return null;

        var file_it = seen_files.keyIterator();
        while (file_it.next()) |path_ptr| {
            result.appendAssumeCapacity(path_ptr.*);
        }

        return result.toOwnedSlice(allocator) catch {
            result.deinit(allocator);
            return null;
        };
    }

    pub fn fileCount(self: *SparseNgramIndex) u32 {
        return @intCast(self.file_ngrams.count());
    }
};

